        name = "Albatross Chick",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Sparse primary spawns, a time window or awkward terrain can extend the search.\n\n1. Enable Track Pets on the minimap and bring a capture pet such as Terrible Turnip with Weakening Blow or Grumpy with Superbark. Bring two healthy supporting pets to finish the enemy team.\n\n2. Search the little islands north of Faronaar at 30.2,25.4 and 31.2,35.6 in Azsuna, or Gull Rock around 80.3,65.0 in Stormheim. Birds often fly above interaction range: stand beneath one and wait for it to swoop down. Only some chicks are battle pets; check several coastal spawns rather than waiting beside an ordinary critter.\n\n3. Engage the green-paw pet from clear ground. If this species is in a secondary slot, defeat the pet ahead of it first. Reduce Albatross Chick below 35% health, stop heavy attacks and use Trap until it succeeds.\n\n4. Defeat the remaining enemy pets to keep your capture. Only one opponent can be trapped per battle. Heal your team before another attempt; do not discard a low-quality capture while waiting for a rare.",
