        description = "Capture Long-Eared Owl in a wild pet battle in Highmountain and Stormheim.",
        difficulty = "medium",
        difficultyReason = "Sparse primary spawns, a time window or awkward terrain can extend the search.",
        requirements = "Battle Pet Training, a trap and a healthy team for level-23 to level-25 wild pets",
        cost = "No currency; wild captures cannot be caged",
        commentIDs = { 2421648, 2478421, 3175795, 3196473, 5323134 },
        tips = "Capture any quality and upgrade it with a battle-stone later. A normal critter without a green paw cannot be trapped. Clear nearby enemies before starting; avoid character attacks and damage-over-time effects on the desired pet.",
        waypoints = {
            { mapID = 650, x = 0.58, y = 0.276, step = 2, label = "Prepfoot - accessible owl search" },
            { mapID = 650, x = 0.552, y = 0.652, step = 2, label = "Highmountain slopes - alternate owls" },
            { mapID = 634, x = 0.324, y = 0.506, step = 2, label = "Stony Highlands - owl search" },
            {
                mapID = 634,
                x = 0.46399999999999997,
                y = 0.5820000000000001,
                step = 2,
                label = "Cullen's Post area - alternate owl",
            },
        },
        npcId = 97118,
        petNPCID = 97118,
        name = "Long-Eared Owl",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Sparse primary spawns, a time window or awkward terrain can extend the search.\n\n1. Enable Track Pets on the minimap and bring a capture pet such as Terrible Turnip with Weakening Blow or Grumpy with Superbark. Bring two healthy supporting pets to finish the enemy team.\n\n2. Try Prepfoot at 58,27.6 in Highmountain, then the slopes at 55.2,65.2. Stormheim alternatives include 32.4,50.6 and 46.4,58.2. Some owls sit over obstructed terrain: move to flat ground and use Interact With Target, or choose another spawn. Do not taunt the owl into combat; replies warn that this prevents pet battling it.\n\n3. Engage the green-paw pet from clear ground. If this species is in a secondary slot, defeat the pet ahead of it first. Reduce Long-Eared Owl below 35% health, stop heavy attacks and use Trap until it succeeds.\n\n4. Defeat the remaining enemy pets to keep your capture. Only one opponent can be trapped per battle. Heal your team before another attempt; do not discard a low-quality capture while waiting for a rare.",
        wowheadUrl = "https://www.wowhead.com/npc=97118",
        references = {
            "https://www.wowhead.com/npc=97118",
            "https://www.wowhead.com/npc=97118#comments:id=2421648",
            "https://www.wowhead.com/npc=97118#comments:id=2478421",
            "https://www.wowhead.com/npc=97118#comments:id=3175795",
            "https://www.wowhead.com/npc=97118#comments:id=3196473",
            "https://www.wowhead.com/npc=97118#comments:id=5323134",
        },
    },
