    [1716] = {
        category = "Reputation",
        source = "Marin Bladewing - The Wardens Revered",
        itemId = 136898,
        description = "A reputation vendor companion. A traded caged copy bypasses the vendor reputation requirement.",
        difficulty = "medium",
        difficultyReason = "The purchase is guaranteed after a reputation grind; a caged pet avoids the grind.",
        requirements = "Revered with The Wardens to buy from the vendor",
        cost = "500 gold before reputation discounts",
        commentIDs = { 2332734, 2477451 },
        waypoints = { { mapID = 630, x = 0.48200000000000004, y = 0.738, step = 3, label = "Marin Bladewing - Fledgling Warden Owl" } },
        npcId = 97128,
        petNPCID = 97128,
        name = "Fledgling Warden Owl",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Reputation",
        stepCount = 4,
        acquisition = "Difficulty: Medium - The purchase is guaranteed after a reputation grind; a caged pet avoids the grind.\n\n1. Choose between buying a caged Fledgling Warden Owl on the Auction House or earning it from the faction vendor. The vendor's reputation restriction is not a requirement to learn a caged pet.\n\n2. Unlock Broken Isles world quests through Uniting the Isles. Complete Wardens-marked world quests and their emissary when active. Save Wardens reputation tokens for the character making the purchase; ordinary Azsuna story quests mostly reward Court of Farondis reputation instead.\n\n3. When The Wardens is Revered, visit Marin Bladewing at the recorded destination. Bring 500 gold before any reputation discount and buy Fledgling Warden Owl.\n\n4. Use the pet item to learn it, then check your Pet Journal. It is a companion purchase; there is no wild capture or pet-battle victory required.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=97128",
        references = {
            "https://www.wowhead.com/npc=97128",
            "https://www.wowhead.com/item=136898",
            "https://www.wowhead.com/npc=97128#comments:id=2332734",
            "https://www.wowhead.com/npc=97128#comments:id=2477451",
        },
    },
    [1717] = {
