        petNPCID = 97174,
        name = "Extinguished Eye",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Reputation",
        stepCount = 4,
        acquisition = "Difficulty: Medium - The purchase is guaranteed after a reputation grind; a caged pet avoids the grind.\n\n1. Choose between buying a caged Extinguished Eye on the Auction House or earning it from the faction vendor. The vendor's reputation restriction is not a requirement to learn a caged pet.\n\n2. Complete Suramar's Nightfall introduction to establish Shal'Aran, then earn Nightfallen reputation from the Suramar story, Nightfallen world quests, emissaries and Withered Army Training. Enter Shal'Aran from 34.8,48.0 if approaching from outside; feed Thalyssra Ancient Mana if hunger prevents dialogue.\n\n3. When The Nightfallen is Revered, visit First Arcanist Thalyssra at the recorded destination. Bring 500 gold before any reputation discount and buy Extinguished Eye.\n\n4. Use the pet item to learn it, then check your Pet Journal. It is a companion purchase; there is no wild capture or pet-battle victory required.",
