    [1718] = {
        category = "Order Hall",
        source = "The Twisting Nether (Demon Hunter) or Demonic Offering (Warlock)",
        itemId = 136900,
        description = "A demon-summon reward obtainable through either of two Legion class halls.",
        difficulty = "medium",
        difficultyReason = "Requires second-tier research and random daily demon loot; the Warlock ritual needs helpers.",
        requirements = "Demon Hunter or Warlock for acquisition; the learned pet is account-wide",
        commentIDs = { 2339337 },
        references = {
            "https://www.wowhead.com/item=136900/hateful-eye#comments:id=2380665",
            "https://www.wowhead.com/item=136900/hateful-eye#comments:id=5413150",
            "https://www.wowhead.com/item=136900/hateful-eye#comments:id=6171983",
            "https://www.wowhead.com/npc=97178",
            "https://www.wowhead.com/item=136900",
            "https://www.wowhead.com/npc=97178#comments:id=2339337",
        },
        waypoints = { { mapID = 717, x = 0.522, y = 0.21899999999999997, step = 3, label = "Dreadscar Rift - Warlock ritual portal" } },
        areaMaps = { 720, 721 },
        npcId = 97178,
        petNPCID = 97178,
        name = "Hateful Eye",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Order Hall",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Requires second-tier research and random daily demon loot; the Warlock ritual needs helpers.\n\n1. Establish the Legion Order Hall on a Demon Hunter or Warlock. Progress its introduction and mission / champion quests until Order Hall advancements are available, then finish the first research tier.\n\n2. For the simpler solo route, choose The Twisting Nether as the Demon Hunter's second-tier advancement in the Fel Hammer. Once ready, use its portal / summoning book near Loramus to reach the daily demon, defeat it and loot it.\n\n3. Alternatively choose Demonic Offering on a Warlock. Use the unlocked Ritual of Doom with two other Warlocks in Dreadscar Rift; the ritual portal is in the north of the hall around 52.2,21.9. Your helpers need hall access, but do not all need to own the upgrade.\n\n4. Repeat the eligible demon summon on later days until Hateful Eye drops, then use the item to learn it. The pet cannot be caged, so ordinary Auction House trading is not an alternative. Other classes can summon it after the account learns it.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=97178",
    },
    [1719] = {
        category = "Drops",
        source = "Felsoul Inquisitors - Felsoul Hold / Soul Vaults, Suramar",
        itemId = 136901,
        description = "A low-chance drop from the inquisitor demons, rather than a wild eye to capture.",
