        name = "Eye of Inquisition",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Drops",
        stepCount = 3,
        acquisition = "Difficulty: Medium - Requires farming ordinary inquisitors for a low-chance drop.\n\n1. Go to Felsoul Hold in southern Suramar. Search the inquisitor groups around 29.6,82.4 and the Soul Vaults area; the recorded points are farm areas rather than fixed rare spawns.\n\n2. Kill and loot Felsoul Inquisitors, checking the mob name rather than killing every demon or eye indiscriminately. Move between groups while they respawn.\n\n3. Continue until Eye of Inquisition drops and use the item to learn it. There is no guaranteed drop after a certain number of kills. Since the pet can be caged, compare a caged copy on the Auction House if the farm is taking too long.",
