    [1720] = {
        category = "Quest Rewards",
        source = "On the Brink - Azurewing Repose, Azsuna",
        itemId = 129178,
        description = "Senegos's dragonflight offers this young blue dragon as a story reward.",
        difficulty = "easy",
        difficultyReason = "A guaranteed reward during the Azurewing Repose story.",
        commentIDs = { 2327323, 2378227, 2384183 },
        waypoints = { { mapID = 630, x = 0.48, y = 0.25, step = 1, label = "Azurewing Repose - Senegos / Emmigosa story" } },
        npcId = 97207,
        petNPCID = 97207,
        name = "Emmigosa",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Quest Rewards",
        stepCount = 4,
        acquisition = "Difficulty: Easy - A guaranteed reward during the Azurewing Repose story.\n\n1. Follow Azsuna's main story from Illidari Stand to Azurewing Repose at 48,25. Meet Senegos, Stellagosa and the young blue dragons.\n\n2. Complete the local quests helping Senegos and defending the repose from the withered attackers. Continue the dragon story until On the Brink becomes available.\n\n3. Complete On the Brink and claim the Emmigosa pet item. This is the Azsuna quest reward, not a random Azure Whelpling drop or a Dragonflight Azure Archives reward.\n\n4. Use Emmigosa to learn the pet. A caged copy may also be bought from another player without repeating the Azsuna story.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=97207",
