    [1721] = {
        category = "Drops",
        source = "Stormwing Matriarch - Stormwing Rookery, Stormheim",
        itemId = 129208,
        description = "Loot a storm dragon whelp from the matriarch above southern Stormheim.",
        difficulty = "easy",
        difficultyReason = "A readily reached outdoor dragon with repeatable pet loot.",
        commentIDs = { 2330937, 2368445, 2429894, 2554675, 2622987 },
        waypoints = { { mapID = 634, x = 0.495, y = 0.715, step = 1, label = "Stormwing Rookery - Stormwing Matriarch" } },
        npcId = 97205,
        petNPCID = 97205,
        name = "Stormborne Whelpling",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Drops",
        stepCount = 3,
        acquisition = "Difficulty: Easy - A readily reached outdoor dragon with repeatable pet loot.\n\n1. Fly to Stormwing Rookery at 49.5,71.5 in Stormheim. Without flight, take the narrow mountain path from Hafr Fjall / Dreadwake's Landing on the eastern side; the grapple route is optional if you have the Grapple Launcher.\n\n2. Defeat Stormwing Matriarch and loot Stormborne Whelpling. The mob is a character-combat rare, not a pet-battle target.\n\n3. Use the whelpling item to learn the pet. Comments confirm pet loot on repeat kills, so another respawn can be useful if you want a spare; do not assume every Broken Isles rare follows this exception.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=97205",
        references = {
