    [1722] = {
        category = "Pet Battles",
        source = "Wild capture after Xavius in The Emerald Nightmare",
        description = "Capture a whelp in the cleansed dream after the raid's final boss.",
        difficulty = "easy",
        difficultyReason = "Legacy Raid Finder provides a short route directly to Xavius, followed by a normal wild capture.",
        commentIDs = { 2411713, 2412340, 2412455, 3151762, 3155815 },
        waypoints = {
            { mapID = 627, x = 0.636, y = 0.555, step = 1, label = "Archmage Timear - Rift of Aln Raid Finder" },
            { mapID = 641, x = 0.564, y = 0.37, step = 1, label = "The Emerald Nightmare - full raid entrance" },
        },
        npcId = 97206,
        petNPCID = 97206,
        name = "Dream Whelpling",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Easy - Legacy Raid Finder provides a short route directly to Xavius, followed by a normal wild capture.\n\n1. Bring a healthy capture team to Archmage Timear at 63.6,55.5 in Broken Isles Dalaran. Queue for The Emerald Nightmare's Rift of Aln legacy Raid Finder wing to go directly to Xavius. Alternatively enter the full raid at 56.4,37.0 in Val'sharah and clear it normally.\n\n2. Defeat Xavius and enter the peaceful cleansed dream. Do not leave through the exit portal: look for green-paw Dream Whelplings around the spirits. They are available in Raid Finder as well as the ordinary raid.\n\n3. Start a wild pet battle and inspect all three slots: the companions can also be Dream Whelplings. Bring Weakening Blow or Superbark because a strong humanoid attack can accidentally kill them, and their healing can lift them above capture range again.\n\n4. Reduce the desired whelp below 35% health, trap it and finish the battle. The pets respawn, so stay for another attempt if needed. If the battle fails to start on a pet class, dismiss your combat pet and try again.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=97206",
        references = {
            "https://www.wowhead.com/npc=97206",
            "https://www.wowhead.com/npc=97206#comments:id=2411713",
            "https://www.wowhead.com/npc=97206#comments:id=2412340",
            "https://www.wowhead.com/npc=97206#comments:id=2412455",
            "https://www.wowhead.com/npc=97206#comments:id=3151762",
            "https://www.wowhead.com/npc=97206#comments:id=3155815",
        },
    },
    [1723] = {
        category = "Drops",
        source = "Dragons of Nightmare - The Emerald Nightmare",
        itemId = 140269,
        description = "A raid-boss pet drop, separate from the capturable Dream Whelpling after Xavius.",
        difficulty = "medium",
        difficultyReason = "A random raid reward limited by boss-loot lockouts.",
        commentIDs = { 2373450, 2448723 },
        waypoints = { { mapID = 641, x = 0.564, y = 0.37, step = 1, label = "The Emerald Nightmare entrance - Dragons of Nightmare" } },
        npcId = 112015,
        petNPCID = 112015,
        name = "Nightmare Whelpling",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Drops",
        stepCount = 3,
        acquisition = "Difficulty: Medium - A random raid reward limited by boss-loot lockouts.\n\n1. Enter The Emerald Nightmare at 56.4,37.0 in Val'sharah on a loot-eligible legacy raid difficulty. Progress through Nythendra and take the portal to the Dragons of Nightmare encounter.\n\n2. Defeat the encounter led by Ysondre and loot the shared reward for Nightmare Whelpling. A matching physical plush does not include a code for this in-game pet.\n\n3. Repeat on eligible difficulties / characters after checking their raid lockouts, or buy a caged copy. Use the pet item when it drops. Clearing Xavius for wild Dream Whelplings is a different acquisition route for a different species.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=112015",
        references = {
            "https://www.wowhead.com/npc=112015",
            "https://www.wowhead.com/item=140269",
