        legionPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Easy - An ordinary wild capture with a prepared level-25 team.\n\n1. Enable Track Pets on the minimap and bring a capture pet such as Terrible Turnip with Weakening Blow or Grumpy with Superbark. Bring two healthy supporting pets to finish the enemy team.\n\n2. Enter Neltharion's Vault from Highmountain at 44.6,72.4 beside Obsidian Overlook, or search the Witchwood / Bloodhunt Highland around 45,35. The spider burrows and can be nearly invisible; use the green paw and Interact With Target. Do not put cave-floor coordinates onto the outdoor Highmountain map.\n\n3. Engage the green-paw pet from clear ground. If this species is in a secondary slot, defeat the pet ahead of it first. Reduce Burrow Spiderling below 35% health, stop heavy attacks and use Trap until it succeeds.\n\n4. Defeat the remaining enemy pets to keep your capture. Only one opponent can be trapped per battle. Heal your team before another attempt; do not discard a low-quality capture while waiting for a rare.",
