        waypoints = { { mapID = 630, x = 0.484, y = 0.626, step = 2, label = "Oceanus Cove - coastal Scuttlebacks" } },
        npcId = 97283,
        petNPCID = 97283,
        name = "Juvenile Scuttleback",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Easy - An ordinary wild capture with a prepared level-25 team.\n\n1. Enable Track Pets on the minimap and bring a capture pet such as Terrible Turnip with Weakening Blow or Grumpy with Superbark. Bring two healthy supporting pets to finish the enemy team.\n\n2. Search the Mak'rana coastline and Grey Shoals; Oceanus Cove at 48.4,62.6 is another documented capture site. Ordinary Scuttleback critters are widespread inland and cannot be trapped. Check the shore's green paws and cycle unwanted crab/snail pet spawns if none are available. Stand on dry ground before engaging.\n\n3. Engage the green-paw pet from clear ground. If this species is in a secondary slot, defeat the pet ahead of it first. Reduce Juvenile Scuttleback below 35% health, stop heavy attacks and use Trap until it succeeds.\n\n4. Defeat the remaining enemy pets to keep your capture. Only one opponent can be trapped per battle. Heal your team before another attempt; do not discard a low-quality capture while waiting for a rare.",
        wowheadUrl = "https://www.wowhead.com/npc=97283",
        references = {
