        source = "Wild capture - Felbane Camp, Highmountain and northern Stormheim",
        description = "Capture Mist Fox Kit in a wild pet battle in Felbane Camp, Highmountain and northern Stormheim.",
        difficulty = "easy",
        difficultyReason = "An ordinary wild capture with a prepared level-25 team.",
        requirements = "Battle Pet Training, a trap and a healthy team for level-23 to level-25 wild pets",
        cost = "No currency; wild captures cannot be caged",
        commentIDs = { 2379363, 2405857, 2558960, 2573350 },
        tips = "Capture any quality and upgrade it with a battle-stone later. A normal critter without a green paw cannot be trapped. Clear nearby enemies before starting; avoid character attacks and damage-over-time effects on the desired pet.",
        waypoints = {
            { mapID = 650, x = 0.316, y = 0.354, step = 2, label = "Felbane Camp path - Mist Fox Kit" },
            { mapID = 650, x = 0.302, y = 0.414, step = 2, label = "Blind Marshlands - alternative kits" },
            { mapID = 650, x = 0.408, y = 0.35200000000000004, step = 2, label = "Witchwood - alternate kits" },
            { mapID = 634, x = 0.537, y = 0.3, step = 2, label = "Stormtorn Foothills - alternative kits" },
        },
        npcId = 97743,
        petNPCID = 97743,
        name = "Mist Fox Kit",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Easy - An ordinary wild capture with a prepared level-25 team.\n\n1. Enable Track Pets on the minimap and bring a capture pet such as Terrible Turnip with Weakening Blow or Grumpy with Superbark. Bring two healthy supporting pets to finish the enemy team.\n\n2. Fly to Felbane Camp and follow the path down toward the Blind Marshlands. Check 31.6,35.4 and 30.2,41.4; the Witchwood near 40.8,35.2 is another site. In Stormheim try 53.7,30.0 by Stormtorn Foothills. If only critters are present, clear other pets and revisit the path after respawns.\n\n3. Engage the green-paw pet from clear ground. If this species is in a secondary slot, defeat the pet ahead of it first. Reduce Mist Fox Kit below 35% health, stop heavy attacks and use Trap until it succeeds.\n\n4. Defeat the remaining enemy pets to keep your capture. Only one opponent can be trapped per battle. Heal your team before another attempt; do not discard a low-quality capture while waiting for a rare.",
        wowheadUrl = "https://www.wowhead.com/npc=97743",
        references = {
            "https://www.wowhead.com/npc=97743",
            "https://www.wowhead.com/npc=97743#comments:id=2379363",
            "https://www.wowhead.com/npc=97743#comments:id=2405857",
            "https://www.wowhead.com/npc=97743#comments:id=2558960",
            "https://www.wowhead.com/npc=97743#comments:id=2573350",
        },
    },
