        commentIDs = { 2382966, 2398874, 2405055, 2412640, 2435458 },
        tips = "Capture any quality and upgrade it with a battle-stone later. A normal critter without a green paw cannot be trapped. Clear nearby enemies before starting; avoid character attacks and damage-over-time effects on the desired pet.",
        waypoints = {
            { mapID = 634, x = 0.546, y = 0.39399999999999996, step = 2, label = "Tideskorn Harbor - Tiny Apparitions" },
            { mapID = 634, x = 0.5720000000000001, y = 0.36, step = 2, label = "Helmouth Shallows - northern search" },
            { mapID = 634, x = 0.578, y = 0.45, step = 2, label = "Harbor - southern search" },
        },
        npcId = 97952,
        petNPCID = 97952,
        name = "Tiny Apparition",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Sparse primary spawns, a time window or awkward terrain can extend the search.\n\n1. Enable Track Pets on the minimap and bring a capture pet such as Terrible Turnip with Weakening Blow or Grumpy with Superbark. Bring two healthy supporting pets to finish the enemy team.\n\n2. Circle the harbor at 54.6,39.4, 57.2,36.0 and 57.8,45.0. If only ordinary Apparitions are present, battle or clear unwanted Kelp Scuttlers and Rapana Whelks as well, then revisit the harbor. You can engage a flying green-paw Apparition without waiting for it to land. Do not assume every ghost critter is capturable.\n\n3. Engage the green-paw pet from clear ground. If this species is in a secondary slot, defeat the pet ahead of it first. Reduce Tiny Apparition below 35% health, stop heavy attacks and use Trap until it succeeds.\n\n4. Defeat the remaining enemy pets to keep your capture. Only one opponent can be trapped per battle. Heal your team before another attempt; do not discard a low-quality capture while waiting for a rare.",
        wowheadUrl = "https://www.wowhead.com/npc=97952",
