    [1752] = {
        category = "Drops",
        source = "Tenpak Flametotem",
        itemId = 129175,
        description = "Obtain the pet item from Tenpak Flametotem; do not try to trap the combat NPC.",
        difficulty = "easy",
        difficultyReason = "A short outdoor encounter; the pet is obtained from ordinary loot.",
        commentIDs = { 2297754, 2406613, 2416025 },
        waypoints = { { mapID = 650, x = 0.418, y = 0.414, step = 1, label = "Tenpak Flametotem - Crispin" } },
        npcId = 98077,
        petNPCID = 98077,
        name = "Crispin",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Drops",
        stepCount = 3,
        acquisition = "Difficulty: Easy - A short outdoor encounter; the pet is obtained from ordinary loot.\n\n1. Go to Tenpak's hut at 41.8,41.4 in Highmountain's Haglands. Fly up or use the uphill path starting near 44,32; he is high on the cliff, not down inside Rockcrawler Chasm.\n\n2. Defeat Tenpak Flametotem and loot the body / event reward for Crispin. Keep the pet item rather than selling it with ordinary loot.\n\n3. Use Crispin to learn the pet. If your eligible loot does not contain it, check again on another eligible character or a later reset; a completed rare-event achievement alone does not teach the pet. A caged copy is an alternative where available.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=98077",
        references = {
            "https://www.wowhead.com/npc=98077",
            "https://www.wowhead.com/item=129175",
