            "https://www.wowhead.com/npc=98077#comments:id=2406613",
            "https://www.wowhead.com/npc=98077#comments:id=2416025",
        },
    },
    [1753] = {
        category = "Drops",
        source = "Soulthirster - Helheim, Stormheim",
        itemId = 129188,
        difficulty = "medium",
        commentIDs = { 2367978, 2439282 },
        description = "A random drop from the Helheim rare, separate from the other jelly pets.",
        difficultyReason = "The rare is straightforward, but the pet can require repeated eligible visits.",
        waypoints = {
            { mapID = 634, x = 0.737, y = 0.39299999999999996, step = 1, label = "Haustvald - return portal to Helheim" },
            { mapID = 649, x = 0.27399999999999997, y = 0.634, step = 2, label = "Soulthirster - water below western bridge" },
        },
        npcId = 98116,
        petNPCID = 98116,
        name = "Bleakwater Jelly",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Drops",
        stepCount = 3,
        acquisition = "Difficulty: Medium - The rare is straightforward, but the pet can require repeated eligible visits.\n\n1. Reach Helheim through the Stormheim story, or return through the portal in the cage at Haustvald, 73.5,39.5 in Stormheim. Use the Helheim map once inside; outdoor Stormheim coordinates do not describe the rare's position.\n\n2. In Helheim, go left through the fog past the sleeping hound, follow the wooden bridge west and jump into the water at its end. Defeat Soulthirster at 27.4,63.4 on the Helheim map.\n\n3. Loot for Bleakwater Jelly and use the item if it drops. Retry on another eligible character or a later daily reset; repeated same-day kills are not unlimited rare-loot attempts. A caged pet from the Auction House is an alternative.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=98116",
        references = {
            "https://www.wowhead.com/npc=98116",
            "https://www.wowhead.com/item=129188",
            "https://www.wowhead.com/npc=98116#comments:id=2367978",
            "https://www.wowhead.com/npc=98116#comments:id=2439282",
        },
    },
    [1754] = {
        category = "Vendor",
        source = "Laura Malley - Underbelly, Broken Isles Dalaran",
        itemId = 136904,
        description = "A guaranteed sewer-vendor purchase using Sightless Eyes; a caged copy is also tradable.",
        difficulty = "easy",
        difficultyReason = "Only 250 Eyes are required and sewer PvE activities can supply them.",
        cost = "250 Sightless Eyes",
        commentIDs = { 2341656 },
        waypoints = {
            { mapID = 629, x = 0.68, y = 0.58, step = 1, label = "Raethan - optional personal guard" },
            { mapID = 629, x = 0.574, y = 0.58, step = 3, label = "Laura Malley - Sewer-Pipe Jelly" },
        },
        npcId = 98128,
        petNPCID = 98128,
        name = "Sewer-Pipe Jelly",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Vendor",
        stepCount = 3,
        acquisition = "Difficulty: Easy - Only 250 Eyes are required and sewer PvE activities can supply them.\n\n1. Enter the Underbelly beneath Broken Isles Dalaran. Hire a personal guard from Raethan near 68,58 or collect during the guards' safe phase if you want to avoid the arena's free-for-all PvP.\n\n2. Earn 250 Sightless Eyes by killing and looting sewer rares / summoned mobs, battling Blind Rats or fishing where the currency is available. PvP kills are not required. Re-hire your guard when its protection expires.\n\n3. Find Laura Malley near 57.4,58.0 on the Underbelly map. Buy Sewer-Pipe Jelly for 250 Eyes and use the pet item. This purchase does not require summoning and trapping the turtles she also sells.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=98128",
        references = {
            "https://www.wowhead.com/npc=98128",
            "https://www.wowhead.com/item=136904",
            "https://www.wowhead.com/npc=98128#comments:id=2341656",
        },
    },
    [1756] = {
        category = "Professions",
        source = "Legion Alchemy: Transmute: Meat to Pet -> Pulsating Sac -> Growling Sac",
        itemId = 136905,
        description = "A random pet from the seven-day Legion Alchemy sac. The other possible outcomes include ordinary older pets.",
        difficulty = "medium",
        difficultyReason = "Recipe discoveries and seven-day random hatches can take several weeks; a caged pet is the faster alternative.",
        commentIDs = { 2362311 },
        references = {
            "https://www.wowhead.com/spell=213256/transmute-meat-to-pet#comments:id=5440363",
            "https://www.wowhead.com/npc=98172",
            "https://www.wowhead.com/item=136905",
            "https://www.wowhead.com/npc=98172#comments:id=2362311",
        },
        tips = "Use the Legion recipe, not the similarly named BfA version. The sac is unique: open the matured Growling Sac before making another Pulsating Sac. The pet you want is not guaranteed, and neither an old local price nor a fixed number of attempts is reliable.",
        waypoints = {
            { mapID = 627, x = 0.415, y = 0.326, step = 1, label = "Dalaran alchemy shop - quests, recipes and station" },
            { mapID = 630, x = 0.61, y = 0.41, step = 2, label = "Eye of Azshara dungeon - Put a Cork in It" },
            { mapID = 650, x = 0.496, y = 0.6859999999999999, step = 2, label = "Neltharion's Lair - Potent Powder" },
        },
        npcId = 98172,
        petNPCID = 98172,
        name = "Ridgeback Piglet",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Professions",
        stepCount = 5,
        acquisition = "Difficulty: Medium - Recipe discoveries and seven-day random hatches can take several weeks; a caged pet is the faster alternative.\n\n1. Check the Auction House for a caged Ridgeback Piglet if you want to bypass the Alchemy process. To make your own attempts, learn Legion Alchemy in Dalaran's alchemy shop at 41.5,32.6.\n\n2. Follow Deucus Valdera's profession quests: Get Your Mix On, the Azsuna shipment and Mysterious Text, then the scribe / Ancient Knowledge / Dormant Burner / Ley Hunting sequence. Continue through Eye of Azshara: Put a Cork in It, the Furbolg and flask quests, and Neltharion's Lair: Potent Powder until Wild Transmutations is available from Patricia Egan in the same shop.\n\n3. Use Wild Transmutations at the Dalaran alchemy station each day until you discover Transmute: Meat to Pet. Use the other discovered Legion transmutes to produce one each of Oily, Bloody and Black Transmutagen; these are separate ingredients, not interchangeable stacks.\n\n4. For each Meat to Pet attempt, gather 3 Fatty Bearsteak, 20 Unbroken Claws, 20 Unbroken Teeth and one of each of the three Transmutagens. Cast the recipe when its shared daily transmute cooldown is ready.\n\n5. Keep the Pulsating Sac until its seven-day real-time timer finishes and it becomes a Growling Sac. Open it and learn Ridgeback Piglet if that is the result. Otherwise repeat the transmute and maturation process; getting an older vendor pet is a normal outcome.",
        wowheadUrl = "https://www.wowhead.com/npc=98172",
    },
    [1759] = {
        category = "Professions",
        source = "Legion Alchemy: Transmute: Meat to Pet -> Pulsating Sac -> Growling Sac",
        itemId = 136908,
        description = "A random pet from the seven-day Legion Alchemy sac. The other possible outcomes include ordinary older pets.",
