        npcId = 98183,
        petNPCID = 98183,
        name = "Thaumaturgical Piglet",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Professions",
        stepCount = 5,
        acquisition = "Difficulty: Medium - Recipe discoveries and seven-day random hatches can take several weeks; a caged pet is the faster alternative.\n\n1. Check the Auction House for a caged Thaumaturgical Piglet if you want to bypass the Alchemy process. To make your own attempts, learn Legion Alchemy in Dalaran's alchemy shop at 41.5,32.6.\n\n2. Follow Deucus Valdera's profession quests: Get Your Mix On, the Azsuna shipment and Mysterious Text, then the scribe / Ancient Knowledge / Dormant Burner / Ley Hunting sequence. Continue through Eye of Azshara: Put a Cork in It, the Furbolg and flask quests, and Neltharion's Lair: Potent Powder until Wild Transmutations is available from Patricia Egan in the same shop.\n\n3. Use Wild Transmutations at the Dalaran alchemy station each day until you discover Transmute: Meat to Pet. Use the other discovered Legion transmutes to produce one each of Oily, Bloody and Black Transmutagen; these are separate ingredients, not interchangeable stacks.\n\n4. For each Meat to Pet attempt, gather 3 Fatty Bearsteak, 20 Unbroken Claws, 20 Unbroken Teeth and one of each of the three Transmutagens. Cast the recipe when its shared daily transmute cooldown is ready.\n\n5. Keep the Pulsating Sac until its seven-day real-time timer finishes and it becomes a Growling Sac. Open it and learn Thaumaturgical Piglet if that is the result. Otherwise repeat the transmute and maturation process; getting an older vendor pet is a normal outcome.",
        wowheadUrl = "https://www.wowhead.com/npc=98183",
    },
