        stepCount = 4,
        acquisition = "Difficulty: Medium - Sparse primary spawns, a time window or awkward terrain can extend the search.\n\n1. Enable Track Pets on the minimap and bring a capture pet such as Terrible Turnip with Weakening Blow or Grumpy with Superbark. Bring two healthy supporting pets to finish the enemy team.\n\n2. Check Rockcrawler Chasm's entrance at 51.6,37.5, Mucksnout Den at 41.5,46.7 and Neltharion's Vault at 45,72.6. Search inside each cave, including side loops. Echo Batlings are the cave bats; Hog-Nosed Bats are outdoors above the caves. Some ordinary bat critters cannot be attacked, so rotate between caves instead of trying to kill an invulnerable critter.\n\n3. Engage the green-paw pet from clear ground. If this species is in a secondary slot, defeat the pet ahead of it first. Reduce Echo Batling below 35% health, stop heavy attacks and use Trap until it succeeds.\n\n4. Defeat the remaining enemy pets to keep your capture. Only one opponent can be trapped per battle. Heal your team before another attempt; do not discard a low-quality capture while waiting for a rare.",
