        name = "Hog-Nosed Bat",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Sparse primary spawns, a time window or awkward terrain can extend the search.\n\n1. Enable Track Pets on the minimap and bring a capture pet such as Terrible Turnip with Weakening Blow or Grumpy with Superbark. Bring two healthy supporting pets to finish the enemy team.\n\n2. Fly to the Haglands above Rockcrawler Chasm, or use the uphill paths at 44.7,33.6 and 51.9,34.1. Search outdoors around 50.4,32.0 and 52.4,33.5 near the harpies. Clear other unwanted pet spawns and revisit the hilltop. Do not wait inside the cave: its bats are Echo Batlings. Use a safe capture attack because Reckless Strike can increase the bat's damage taken.\n\n3. Engage the green-paw pet from clear ground. If this species is in a secondary slot, defeat the pet ahead of it first. Reduce Hog-Nosed Bat below 35% health, stop heavy attacks and use Trap until it succeeds.\n\n4. Defeat the remaining enemy pets to keep your capture. Only one opponent can be trapped per battle. Heal your team before another attempt; do not discard a low-quality capture while waiting for a rare.",
