    [1763] = {
        category = "Pet Battles",
        source = "Wild capture - Highmountain's rivers",
        description = "Capture Spiketail Beaver in a wild pet battle in Highmountain's rivers.",
        difficulty = "easy",
        difficultyReason = "An ordinary wild capture with a prepared level-25 team.",
        requirements = "Battle Pet Training, a trap and a healthy team for level-23 to level-25 wild pets",
        cost = "No currency; wild captures cannot be caged",
        commentIDs = { 2379131, 2440486, 2446980, 2569713 },
        tips = "Capture any quality and upgrade it with a battle-stone later. A normal critter without a green paw cannot be trapped. Clear nearby enemies before starting; avoid character attacks and damage-over-time effects on the desired pet.",
        waypoints = {
            { mapID = 650, x = 0.348, y = 0.674, step = 2, label = "Sylvan Falls - beavers / local backlines" },
            { mapID = 650, x = 0.418, y = 0.594, step = 2, label = "Riverbend - alternative beavers" },
        },
        npcId = 98211,
        petNPCID = 98211,
        name = "Spiketail Beaver",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Easy - An ordinary wild capture with a prepared level-25 team.\n\n1. Enable Track Pets on the minimap and bring a capture pet such as Terrible Turnip with Weakening Blow or Grumpy with Superbark. Bring two healthy supporting pets to finish the enemy team.\n\n2. Follow the Riverbend and Sylvan Falls banks around 34.8,67.4 and 41.8,59.4. Beavers also occur as secondary opponents in ordinary Highmountain battles. Capturing a secondary is sufficient for the collection even though replies about falcosaur hunting quests say otherwise; those quest conditions are separate.\n\n3. Engage the green-paw pet from clear ground. If this species is in a secondary slot, defeat the pet ahead of it first. Reduce Spiketail Beaver below 35% health, stop heavy attacks and use Trap until it succeeds.\n\n4. Defeat the remaining enemy pets to keep your capture. Only one opponent can be trapped per battle. Heal your team before another attempt; do not discard a low-quality capture while waiting for a rare.",
        wowheadUrl = "https://www.wowhead.com/npc=98211",
        references = {
            "https://www.wowhead.com/npc=98211",
            "https://www.wowhead.com/npc=98211#comments:id=2379131",
            "https://www.wowhead.com/npc=98211#comments:id=2440486",
            "https://www.wowhead.com/npc=98211#comments:id=2446980",
            "https://www.wowhead.com/npc=98211#comments:id=2569713",
        },
    },
