        acquisition = "Difficulty: Medium - Sparse primary spawns, a time window or awkward terrain can extend the search.\n\n1. Enable Track Pets on the minimap and bring a capture pet such as Terrible Turnip with Weakening Blow or Grumpy with Superbark. Bring two healthy supporting pets to finish the enemy team.\n\n2. Visit the Ley-Ruins around 56,13.8 and 58.6,17.6 during the game's daytime. Erudite and Eldritch Manafiends replace each other with the day/night cycle. If only Eldritch are present, return during daylight; clearing them cannot bypass the time window. Region and daylight-saving differences make old local-clock conversions unreliable. Check the pet's name before engaging and clear nearby hostile mana creatures.\n\n3. Engage the green-paw pet from clear ground. If this species is in a secondary slot, defeat the pet ahead of it first. Reduce Erudite Manafiend below 35% health, stop heavy attacks and use Trap until it succeeds.\n\n4. Defeat the remaining enemy pets to keep your capture. Only one opponent can be trapped per battle. Heal your team before another attempt; do not discard a low-quality capture while waiting for a rare.",
