    [1777] = {
        category = "Order Hall",
        source = "Evergreen soil plots - Druid Dreamgrove",
        itemId = 129362,
        description = "A Druid-only acquisition from grown plants; other classes can summon the pet after it is learned.",
        difficulty = "medium",
        difficultyReason = "Needs Druid Order Hall research and repeated three-day harvests.",
        requirements = "A Druid with Evergreen researched",
        commentIDs = { 2339340, 2351330, 3182513, 5590428 },
        tips = "These pets cannot be caged. No retired artifact-power grind is required. Finish an active artifact introduction and the initial champion/mission sequence if Leafbeard still offers no research; the Dreamgrove Researcher is not the upgrade NPC.",
        waypoints = {
            { mapID = 747, x = 0.336, y = 0.28800000000000003, step = 2, label = "Leafbeard - research Evergreen" },
            { mapID = 747, x = 0.452, y = 0.629, step = 3, label = "Evergreen soil plots - plant and harvest" },
        },
        npcId = 98463,
        petNPCID = 98463,
        name = "Broot",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Order Hall",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Needs Druid Order Hall research and repeated three-day harvests.\n\n1. On a Druid, complete the Legion Dalaran introduction, obtain your first artifact and establish the Dreamgrove. Continue The Eternal Dream / Rise, Champions introduction and its early missions until Branching Out opens Order Hall advancements.\n\n2. Speak to Leafbeard the Storied around 33.6,28.8 in the Dreamgrove. Complete the first research tier, then choose Evergreen in the second tier. If you previously chose its alternative, change to Evergreen and wait for the research to finish.\n\n3. Go to the two soil plots around 45.2,62.9 in the Dreamgrove and plant them. Return after their three-day growth period to harvest, then replant the plots.\n\n4. Loot each grown plant. Grove Vines can contain Broot; ordinary harvests can contain food or other items instead. Repeat the planting / harvesting cycle until the pet drops and learn it on the Druid.",
        wowheadUrl = "https://www.wowhead.com/npc=98463",
        references = {
            "https://www.wowhead.com/npc=98463",
            "https://www.wowhead.com/item=129362",
            "https://www.wowhead.com/npc=98463#comments:id=2339340",
            "https://www.wowhead.com/npc=98463#comments:id=2351330",
            "https://www.wowhead.com/npc=98463#comments:id=3182513",
            "https://www.wowhead.com/npc=98463#comments:id=5590428",
        },
    },
    [1778] = {
        category = "Pet Battle",
        source = "Dusty Rug / Spring Cleaning - Legion Dalaran",
        difficulty = "medium",
        description = "A hidden wild capture revealed by clicking a Dusty Rug.",
        difficultyReason = "First find a temporary rug, then locate and capture a bunny during the buff.",
        commentIDs = { 2334722, 2428043, 2445014, 5243451, 5504983 },
        waypoints = {
            { mapID = 627, x = 0.526, y = 0.3, step = 1, label = "Barber shop - possible Dusty Rug" },
            { mapID = 627, x = 0.59, y = 0.382, step = 1, label = "Magical Menagerie - possible Dusty Rug" },
            { mapID = 627, x = 0.31, y = 0.7290000000000001, step = 1, label = "Greyfang Enclave - possible Dusty Rug" },
            { mapID = 627, x = 0.643, y = 0.38, step = 1, label = "Filthy Animal - possible Dusty Rug" },
        },
        npcId = 98506,
        petNPCID = 98506,
        name = "Dust Bunny",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Pet Battle",
        stepCount = 4,
        acquisition = "Difficulty: Medium - First find a temporary rug, then locate and capture a bunny during the buff.\n\n1. Go to Broken Isles Dalaran. Search for the clickable Dusty Rug in the barber shop at 52.6,30.0, the Magical Menagerie at 59,38.2, and your accessible faction inn: Greyfang Enclave 31,72.9 for Alliance or the Filthy Animal 64.3,38 for Horde. The rug itself has no green pet-battle paw.\n\n2. Click a spawned rug to gain the 15-minute Spring Cleaning buff. Not every rug is clickable and the special rug moves between spawn sites. If none is present, return later rather than fighting ordinary city critters.\n\n3. While Spring Cleaning is active, search Dalaran's main-level streets and grassy edges for green-paw Dust Bunnies. The buff reveals the wild pets to you; another player's visible bunny is not enough without your own buff.\n\n4. Start a pet battle, lower the bunny below 35% health without killing it, trap it and defeat the rest of its team. A poor-quality capture still supplies the species and can be upgraded later with a battle-stone. Refresh the rug buff if it expires before you find one.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=98506",
        references = {
            "https://www.wowhead.com/npc=98506",
            "https://www.wowhead.com/npc=98506#comments:id=2334722",
            "https://www.wowhead.com/npc=98506#comments:id=2428043",
            "https://www.wowhead.com/npc=98506#comments:id=2445014",
            "https://www.wowhead.com/npc=98506#comments:id=5243451",
            "https://www.wowhead.com/npc=98506#comments:id=5504983",
        },
    },
    [1802] = {
        category = "Drops",
        source = "Pollous the Fetid",
        itemId = 130168,
        description = "Obtain the pet item from Pollous the Fetid; do not try to trap the combat NPC.",
        difficulty = "easy",
        difficultyReason = "A short outdoor encounter; the pet is obtained from ordinary loot.",
        commentIDs = { 2299616, 2369123, 2425874 },
        waypoints = {
            {
                mapID = 641,
                x = 0.6759999999999999,
                y = 0.44799999999999995,
                step = 1,
                label = "Pollous the Fetid - Fetid Waveling",
            },
        },
        npcId = 99394,
        petNPCID = 99394,
        name = "Fetid Waveling",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Drops",
        stepCount = 3,
        acquisition = "Difficulty: Easy - A short outdoor encounter; the pet is obtained from ordinary loot.\n\n1. Go to Dreadroot in Val'sharah at 67.6,44.8. Talk to Filandras Mistcaller to begin Purging the River, then fight the elemental he summons. If the event is already active, help finish it; if the NPC offers no dialogue, return after it resets.\n\n2. Defeat Pollous the Fetid and loot the body / event reward for Fetid Waveling. Keep the pet item rather than selling it with ordinary loot.\n\n3. Use Fetid Waveling to learn the pet. If your eligible loot does not contain it, check again on another eligible character or a later reset; a completed rare-event achievement alone does not teach the pet. A caged copy is an alternative where available.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=99394",
        references = {
            "https://www.wowhead.com/npc=99394",
            "https://www.wowhead.com/item=130168",
            "https://www.wowhead.com/npc=99394#comments:id=2299616",
            "https://www.wowhead.com/npc=99394#comments:id=2369123",
            "https://www.wowhead.com/npc=99394#comments:id=2425874",
        },
    },
    [1803] = {
        category = "Drops",
        source = "Dreamweaver Provisions - Dreamweavers emissary",
        itemId = 130167,
        description = "A random pet in the Dreamweavers emissary chest; the reputation vendor sells Ash'ana instead.",
        difficulty = "medium",
        difficultyReason = "The emissary must be active and its chest is not guaranteed to contain the pet.",
        commentIDs = { 2354598, 2392878, 2535915 },
        waypoints = { { mapID = 641, x = 0.547, y = 0.733, step = 3, label = "Sylvia Hartshorn - Dreamweavers emissary reward" } },
        npcId = 99389,
        petNPCID = 99389,
        name = "Thistleleaf Adventurer",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Drops",
        stepCount = 4,
        acquisition = "Difficulty: Medium - The emissary must be active and its chest is not guaranteed to contain the pet.\n\n1. Unlock Broken Isles world quests through Uniting the Isles. Watch for the Dreamweavers emissary on the Broken Isles map.\n\n2. While that emissary is active, complete four world quests that count for Dreamweavers. Ordinary daily reputation gains without the active emissary do not award Dreamweaver Provisions.\n\n3. Hand in the completed emissary to Sylvia Hartshorn in Lorlathil at 54.7,73.3 and open Dreamweaver Provisions. Learn Thistleleaf Adventurer if it drops.\n\n4. Repeat on eligible characters when the emissary returns, or buy a caged pet from another player. Exalted reputation and a Paragon chest are not prerequisites for this original emissary source.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=99389",
        references = {
            "https://www.wowhead.com/npc=99389",
            "https://www.wowhead.com/item=130167",
            "https://www.wowhead.com/npc=99389#comments:id=2354598",
