        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Drops",
        stepCount = 3,
        acquisition = "Difficulty: Easy - A short outdoor encounter; the pet is obtained from ordinary loot.\n\n1. Go to Ravencourt, the outdoor courtyard below Black Rook Hold in Val'sharah at 43.8,53.4. Look inside the cage among sleeping cats for the spectral Darkshade; this is outside the dungeon.\n\n2. Defeat Darkshade and loot the body / event reward for Risen Saber Kitten. Keep the pet item rather than selling it with ordinary loot.\n\n3. Use Risen Saber Kitten to learn the pet. If your eligible loot does not contain it, check again on another eligible character or a later reset; a completed rare-event achievement alone does not teach the pet. A caged copy is an alternative where available.",
