            { mapID = 680, x = 0.34, y = 0.736, step = 2, label = "Felmaw Cavern entrance - search inside" },
            { mapID = 680, x = 0.366, y = 0.716, step = 2, label = "Felmaw Cavern interior - Vicious Broodling" },
        },
        npcId = 99513,
        petNPCID = 99513,
        name = "Vicious Broodling",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Sparse primary spawns, a time window or awkward terrain can extend the search.\n\n1. Enable Track Pets on the minimap and bring a capture pet such as Terrible Turnip with Weakening Blow or Grumpy with Superbark. Bring two healthy supporting pets to finish the enemy team.\n\n2. Circle the Thornclaw Broodling spawns at 25.5,61.7, 29,65 and 29.6,82.5. Clear unwanted Thornclaw critters and battle pets, then check for the red Vicious Broodling. Also enter Felmaw Cavern at 34,73.6 and search inside around 36.6,71.6. Clear demons without hitting the desired spider. Replies warn that forfeiting can lose a scarce spawn, so keep a capture team ready rather than repeatedly restarting for different abilities.\n\n3. Engage the green-paw pet from clear ground. If this species is in a secondary slot, defeat the pet ahead of it first. Reduce Vicious Broodling below 35% health, stop heavy attacks and use Trap until it succeeds.\n\n4. Defeat the remaining enemy pets to keep your capture. Only one opponent can be trapped per battle. Heal your team before another attempt; do not discard a low-quality capture while waiting for a rare.",
        wowheadUrl = "https://www.wowhead.com/npc=99513",
        references = {
            "https://www.wowhead.com/npc=99513",
            "https://www.wowhead.com/npc=99513#comments:id=2387799",
