        },
    },
    [1808] = {
        category = "Treasure",
        source = "Withered Army Training - medium chest in The Collapse",
        itemId = 136914,
        difficulty = "medium",
        description = "Recover the specific five-withered treasure chest inside the Suramar training scenario.",
        difficultyReason = "Requires the Suramar introduction, Ancient Mana and enough surviving Withered to recover the chest.",
        commentUrl = "https://www.wowhead.com/item=136914",
        commentIDs = { 2340620, 2415657 },
        waypoints = {
            { mapID = 680, x = 0.365, y = 0.46799999999999997, step = 2, label = "Shal'Aran - Thalyssra / training entrance" },
        },
        npcId = 99526,
        petNPCID = 99526,
        name = "Leyline Broodling",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Treasure",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Requires the Suramar introduction, Ancient Mana and enough surviving Withered to recover the chest.\n\n1. Progress Suramar's Nightfallen story at Shal'Aran until First Arcanist Thalyssra offers Withered Army Training. Gather Ancient Mana beforehand: the starting army size depends on how much you pay, and a larger army leaves more soldiers after recovering treasures.\n\n2. Enter training through Thalyssra at Shal'Aran, around 36.5,46.8 in Suramar. Keep your army together, collect additional Withered and stun / interrupt dangerous enemies rather than charging far ahead of your escorts.\n\n3. Explore The Collapse and find the medium treasure chest requiring FIVE Withered to transport. Keep at least five alive and interact with that chest to send it out. The five carriers leave your fighting army; do not spend your last soldiers on unrelated chests first.\n\n4. Finish or safely leave the training run and open the recovered chest among the rewards outside. The Leyline Broodling is associated with this specific chest, not a random wild broodling or a score-only chest. Learn the pet; a caged copy is also tradable.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=99526",
        references = {
            "https://www.wowhead.com/npc=99526",
            "https://www.wowhead.com/item=136914",
            "https://www.wowhead.com/item=136914#comments:id=2340620",
            "https://www.wowhead.com/item=136914#comments:id=2415657",
        },
    },
    [1809] = {
        category = "Pet Battles",
        source = "Wild capture - Falanaar's underground tunnels, Suramar",
        description = "Capture Crystalline Broodling in a wild pet battle in Falanaar's underground tunnels, Suramar.",
