            { mapID = 680, x = 0.23800000000000002, y = 0.42, step = 2, label = "Falanaar opening - alternative descent" },
        },
        npcId = 99527,
        petNPCID = 99527,
        name = "Crystalline Broodling",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Easy - An ordinary wild capture with a prepared level-25 team.\n\n1. Enable Track Pets on the minimap and bring a capture pet such as Terrible Turnip with Weakening Blow or Grumpy with Superbark. Bring two healthy supporting pets to finish the enemy team.\n\n2. Enter the Falanaar tunnels from the ravine entrance at 20.8,50.5 or the descent near 23.8,42.0. Search underground, not just the surface dots on the map. The surface entrance pins are approaches, not promises that a spider stands outdoors. You do not need to start Withered Army Training to capture this wild species; Leyline Broodling is a separate treasure reward.\n\n3. Engage the green-paw pet from clear ground. If this species is in a secondary slot, defeat the pet ahead of it first. Reduce Crystalline Broodling below 35% health, stop heavy attacks and use Trap until it succeeds.\n\n4. Defeat the remaining enemy pets to keep your capture. Only one opponent can be trapped per battle. Heal your team before another attempt; do not discard a low-quality capture while waiting for a rare.",
        wowheadUrl = "https://www.wowhead.com/npc=99527",
