        petNPCID = 106152,
        name = "Baby Elderhorn",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Reputation",
        stepCount = 4,
        acquisition = "Difficulty: Medium - The purchase is guaranteed after a reputation grind; a caged pet avoids the grind.\n\n1. Choose between buying a caged Baby Elderhorn on the Auction House or earning it from the faction vendor. The vendor's reputation restriction is not a requirement to learn a caged pet.\n\n2. Complete Highmountain's story and Highmountain Tribe world quests / emissaries until Revered. Ransa is on Thunder Totem's upper platform: use the Thunder Totem local map for her coordinates rather than placing them on the full Highmountain map.\n\n3. When Highmountain Tribe is Revered, visit Ransa Greyfeather at the recorded destination. Bring 500 gold before any reputation discount and buy Baby Elderhorn.\n\n4. Use the pet item to learn it, then check your Pet Journal. It is a companion purchase; there is no wild capture or pet-battle victory required.",
