        legionPetGuide = true,
        sourceType = "Reputation",
        stepCount = 4,
        acquisition = "Difficulty: Medium - The purchase is guaranteed after a reputation grind; a caged pet avoids the grind.\n\n1. Choose between buying a caged Sunborne Val'kyr on the Auction House or earning it from the faction vendor. The vendor's reputation restriction is not a requirement to learn a caged pet.\n\n2. Complete Stormheim's story and Valarjar world quests / emissaries until Revered. The pet is a faction purchase; old comments about a fan-designed special questline do not describe an implemented acquisition route.\n\n3. When Valarjar is Revered, visit Valdemar Stormseeker at the recorded destination. Bring 500 gold before any reputation discount and buy Sunborne Val'kyr.\n\n4. Use the pet item to learn it, then check your Pet Journal. It is a companion purchase; there is no wild capture or pet-battle victory required.",
