    [1886] = {
        category = "Professions",
        source = "Legion Engineering: Trigger Happy; also tradable",
        itemId = 132519,
        description = "A crafted walking gun. Engineering is required to craft it, but buyers can simply learn the pet.",
        difficulty = "medium",
        difficultyReason = "The crafting route needs a profession questline, Halls of Valor and 50 soulbound Blood of Sargeras.",
        commentIDs = { 2330623, 2373814, 2373813, 2401065 },
        waypoints = {
            { mapID = 627, x = 0.384, y = 0.25, step = 2, label = "Hobart's shop - Legion Engineering" },
            { mapID = 634, x = 0.726, y = 0.7040000000000001, step = 2, label = "Halls of Valor - Runestone of Vitality" },
        },
        npcId = 106210,
        petNPCID = 106210,
        name = "Trigger",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Professions",
        stepCount = 4,
        acquisition = "Difficulty: Medium - The crafting route needs a profession questline, Halls of Valor and 50 soulbound Blood of Sargeras.\n\n1. Compare a finished Trigger or caged pet on the Auction House before gathering materials. A buyer does not need to unlock the Engineering schematic.\n\n2. To craft it, learn Legion Engineering from Hobart Grapplehammer in Dalaran and follow the profession quests until Trigger Happy. Complete its Halls of Valor objective by defeating Odyn and obtaining the Runestone of Vitality, then turn in to learn Trigger.\n\n3. Gather 50 Leystone Ore, 30 Oversized Blasting Caps, 20 Loose Trigger mechanisms, 2 Sniping Scopes, 50 Blood of Sargeras and 10 Infernal Brimstone. The soulbound Blood must be supplied by the crafter.\n\n4. Craft Trigger and learn one finished item. Historical reports describe a stack-consumption bug: if you made multiple copies for trading, separate a single item before using it.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=106210",
        references = {
