    [1888] = {
        category = "Vendor",
        source = "The Mad Merchant - The Wonderworks, Broken Isles Dalaran",
        itemId = 136923,
        description = "An expensive celestial companion from an irregularly spawning vendor.",
        difficulty = "hard",
        difficultyReason = "Requires 1,000,000 gold and waiting for the merchant to appear.",
        cost = "1,000,000 gold",
        commentIDs = { 2328403, 2344616, 2448499 },
        waypoints = { { mapID = 627, x = 0.434, y = 0.46799999999999997, step = 2, label = "The Wonderworks - The Mad Merchant" } },
        npcId = 106270,
        petNPCID = 106270,
        name = "Celestial Calf",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Vendor",
        stepCount = 4,
        acquisition = "Difficulty: Hard - Requires 1,000,000 gold and waiting for the merchant to appear.\n\n1. Save 1,000,000 gold, or compare a tradable caged copy on the Auction House if one is listed for less.\n\n2. Enter The Wonderworks toy shop in Broken Isles Dalaran at 43.4,46.8. Look for The Mad Merchant; the ordinary toy-shop vendors do not sell the calf.\n\n3. If he is absent, return later or join a group that reports him present. His appearances are irregular; old four-hour or multi-day observations are not a fixed schedule.\n\n4. Buy Celestial Calf while he is present and use it to learn the companion. Announce the vendor's presence for other collectors while he remains available.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=106270",
        references = {
            "https://www.wowhead.com/npc=106270",
            "https://www.wowhead.com/item=136923",
