        },
    },
    [1907] = {
        category = "Drops",
        source = "Gorebeak",
        itemId = 130154,
        description = "Obtain the pet item from Gorebeak; do not try to trap the combat NPC.",
        difficulty = "easy",
        difficultyReason = "A short outdoor encounter; the pet is obtained from ordinary loot.",
        commentIDs = { 2314247, 2368536, 2425771 },
        waypoints = { { mapID = 641, x = 0.598, y = 0.7759999999999999, step = 1, label = "Gorebeak - Pygmy Owl" } },
        npcId = 108568,
        petNPCID = 108568,
        name = "Pygmy Owl",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Drops",
        stepCount = 3,
        acquisition = "Difficulty: Easy - A short outdoor encounter; the pet is obtained from ordinary loot.\n\n1. Travel southeast from Lorlathil to the Whispering Bluffs in Val'sharah at 59.8,77.6. Talk to Lorel Sagefeather near Tiris Rainshadow to summon Gorebeak. Avoid his marked ground attacks while finishing the event.\n\n2. Defeat Gorebeak and loot the body / event reward for Pygmy Owl. Keep the pet item rather than selling it with ordinary loot.\n\n3. Use Pygmy Owl to learn the pet. If your eligible loot does not contain it, check again on another eligible character or a later reset; a completed rare-event achievement alone does not teach the pet. A caged copy is an alternative where available.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=108568",
        references = {
            "https://www.wowhead.com/npc=108568",
            "https://www.wowhead.com/item=130154",
