        },
    },
    [1911] = {
        category = "Vendor",
        source = "Conjurer Margoss - Margoss's Retreat outside Legion Dalaran",
        itemId = 138810,
        description = "A fishing friendship purchase using Drowned Mana.",
        difficulty = "medium",
        difficultyReason = "A predictable fishing grind with a separate currency cost after the friendship requirement.",
        requirements = "Good Friend with Conjurer Margoss",
        cost = "50 Drowned Mana after Good Friend",
        commentIDs = { 2357318, 2362316 },
        tips = "The fishing island lies outside Dalaran's city-map artwork. The map records the city approach and the Broken Isles overview instead of placing Margoss on an unrelated city street. Drowned Mana is distinct from Ancient Mana.",
        waypoints = {
            { mapID = 627, x = 0.308, y = 0.327, step = 1, label = "Northwest city edge - fly to Margoss's island" },
            { mapID = 629, x = 0.69, y = 0.21, step = 1, label = "Underbelly fishing - optional Emblem of Margoss" },
        },
        areaMaps = { 619 },
        npcId = 109216,
        petNPCID = 109216,
        name = "Sting Ray Pup",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Vendor",
        stepCount = 4,
        acquisition = "Difficulty: Medium - A predictable fishing grind with a separate currency cost after the friendship requirement.\n\n1. Learn Fishing and reach Margoss's Retreat, the floating island northwest of Broken Isles Dalaran. Fly out from the city's northwest edge; alternatively fish an Emblem of Margoss from the Underbelly and use it to teleport to the island.\n\n2. Fish in Margoss's pond for Drowned Mana and complete his introductory turn-in. Hand in Mana for friendship until Good Friend. The ordinary Friendly label in the old catalogue is insufficient for this pet.\n\n3. Use Marks of Aquaos caught in the pond to summon Aquaos, defeat him and fish during the pond bonus. Other anglers can help with the summon. Continue fishing until you have 50 additional Drowned Mana after your friendship turn-ins.\n\n4. Buy Sting Ray Pup from Conjurer Margoss for 50 Drowned Mana and learn it. Keep any extra Mana if you plan to buy his other rewards.",
        wowheadUrl = "https://www.wowhead.com/npc=109216",
        references = {
            "https://www.wowhead.com/npc=109216",
            "https://www.wowhead.com/item=138810",
            "https://www.wowhead.com/npc=109216#comments:id=2357318",
            "https://www.wowhead.com/npc=109216#comments:id=2362316",
        },
    },
    [1912] = {
        category = "Pet Battles",
        source = "Laura Malley's Young Mutant Warturtles item, then wild capture",
        itemId = 139412,
        description = "The purchase summons capturable turtles in the Underbelly; buying the box alone does not learn the pet.",
        difficulty = "medium",
        difficultyReason = "Requires 1,500 Eyes and protecting a normal wild-pet capture in the sewers.",
        cost = "1,500 Sightless Eyes for a summon; another player's turtles can also be captured",
        commentIDs = { 2378296, 2381112, 2381574, 5320610 },
        waypoints = {
            { mapID = 629, x = 0.574, y = 0.58, step = 2, label = "Laura Malley - buy and release Warturtles" },
            { mapID = 629, x = 0.68, y = 0.58, step = 3, label = "Raethan - renew personal guard" },
        },
        npcId = 110666,
        petNPCID = 110666,
        name = "Young Mutant Warturtle",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Requires 1,500 Eyes and protecting a normal wild-pet capture in the sewers.\n\n1. Bring a healthy level-25 capture team to the Underbelly. If another collector has already released green-paw Young Mutant Warturtles, you can battle those directly without buying your own box.\n\n2. Otherwise earn 1,500 Sightless Eyes from sewer activities and buy Young Mutant Warturtles from Laura Malley around 57.4,58.0. This is the plural-named summoning item, not a learned companion.\n\n3. Wait for a safe guard phase or hire a fresh personal guard from Raethan. Use the item beside Laura to release four turtles; other players can capture them too, so have your team ready.\n\n4. Click a turtle even if the cursor does not change into the usual battle icon. Lower its health below 35%, trap it, and defeat its two allies to keep it. Each turtle has its own quality: secure a capture and upgrade it later rather than wasting the summon waiting for a guaranteed rare.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=110666",
        references = {
            "https://www.wowhead.com/npc=110666",
            "https://www.wowhead.com/item=139412",
            "https://www.wowhead.com/npc=110666#comments:id=2378296",
            "https://www.wowhead.com/npc=110666#comments:id=2381112",
            "https://www.wowhead.com/npc=110666#comments:id=2381574",
            "https://www.wowhead.com/npc=110666#comments:id=5320610",
        },
    },
