        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Easy - An ordinary wild capture with a prepared level-25 team.\n\n1. Enable Track Pets on the minimap and bring a capture pet such as Terrible Turnip with Weakening Blow or Grumpy with Superbark. Bring two healthy supporting pets to finish the enemy team.\n\n2. Search Lorlathil at 54,73.8 or the forest near 57.8,65.8. Green-paw fawns may follow a stag and doe; killing the parents is unnecessary. If the cursor does not show a pet-battle symbol, target the fawn and use Interact With Target, or click it directly. Avoid attacking the herd with character abilities.\n\n3. Engage the green-paw pet from clear ground. If this species is in a secondary slot, defeat the pet ahead of it first. Reduce Gleamhoof Fawn below 35% health, stop heavy attacks and use Trap until it succeeds.\n\n4. Defeat the remaining enemy pets to keep your capture. Only one opponent can be trapped per battle. Heal your team before another attempt; do not discard a low-quality capture while waiting for a rare.",
        wowheadUrl = "https://www.wowhead.com/npc=110741",
        references = {
            "https://www.wowhead.com/npc=110741",
            "https://www.wowhead.com/npc=110741#comments:id=2377466",
            "https://www.wowhead.com/npc=110741#comments:id=2378314",
            "https://www.wowhead.com/npc=110741#comments:id=2384650",
            "https://www.wowhead.com/npc=110741#comments:id=2412323",
            "https://www.wowhead.com/npc=110741#comments:id=5800685",
        },
    },
