        legionPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Sparse primary spawns, a time window or awkward terrain can extend the search.\n\n1. Enable Track Pets on the minimap and bring a capture pet such as Terrible Turnip with Weakening Blow or Grumpy with Superbark. Bring two healthy supporting pets to finish the enemy team.\n\n2. Check the hidden pond at 29.2,44.8, the pools near 37,52.2 and 47.8,52.4, and the bank at 47.2,61.6. Clear unwanted Bucktooth Flapper critters and battle pets and revisit the water. Multiple captures in dry weather contradict the old rain-only claim: rain is not required. The beaver is a sparse primary, so do not spend the whole search checking random backlines.\n\n3. Engage the green-paw pet from clear ground. If this species is in a secondary slot, defeat the pet ahead of it first. Reduce Stormstruck Beaver below 35% health, stop heavy attacks and use Trap until it succeeds.\n\n4. Defeat the remaining enemy pets to keep your capture. Only one opponent can be trapped per battle. Heal your team before another attempt; do not discard a low-quality capture while waiting for a rare.",
