    [1920] = {
        category = "Professions",
        source = "Legion Alchemy: Transmute: Meat to Pet -> Pulsating Sac -> Growling Sac",
        itemId = 139789,
        description = "A random pet from the seven-day Legion Alchemy sac. The other possible outcomes include ordinary older pets.",
        difficulty = "medium",
        difficultyReason = "Recipe discoveries and seven-day random hatches can take several weeks; a caged pet is the faster alternative.",
        commentIDs = { 2325151 },
        references = {
            "https://www.wowhead.com/spell=213256/transmute-meat-to-pet#comments:id=5440363",
            "https://www.wowhead.com/npc=111425",
            "https://www.wowhead.com/item=139789",
            "https://www.wowhead.com/npc=111425#comments:id=2325151",
        },
        tips = "Use the Legion recipe, not the similarly named BfA version. The sac is unique: open the matured Growling Sac before making another Pulsating Sac. The pet you want is not guaranteed, and neither an old local price nor a fixed number of attempts is reliable.",
        waypoints = {
            { mapID = 627, x = 0.415, y = 0.326, step = 1, label = "Dalaran alchemy shop - quests, recipes and station" },
            { mapID = 630, x = 0.61, y = 0.41, step = 2, label = "Eye of Azshara dungeon - Put a Cork in It" },
            { mapID = 650, x = 0.496, y = 0.6859999999999999, step = 2, label = "Neltharion's Lair - Potent Powder" },
        },
        npcId = 111425,
        petNPCID = 111425,
        name = "Transmutant",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Professions",
        stepCount = 5,
        acquisition = "Difficulty: Medium - Recipe discoveries and seven-day random hatches can take several weeks; a caged pet is the faster alternative.\n\n1. Check the Auction House for a caged Transmutant if you want to bypass the Alchemy process. To make your own attempts, learn Legion Alchemy in Dalaran's alchemy shop at 41.5,32.6.\n\n2. Follow Deucus Valdera's profession quests: Get Your Mix On, the Azsuna shipment and Mysterious Text, then the scribe / Ancient Knowledge / Dormant Burner / Ley Hunting sequence. Continue through Eye of Azshara: Put a Cork in It, the Furbolg and flask quests, and Neltharion's Lair: Potent Powder until Wild Transmutations is available from Patricia Egan in the same shop.\n\n3. Use Wild Transmutations at the Dalaran alchemy station each day until you discover Transmute: Meat to Pet. Use the other discovered Legion transmutes to produce one each of Oily, Bloody and Black Transmutagen; these are separate ingredients, not interchangeable stacks.\n\n4. For each Meat to Pet attempt, gather 3 Fatty Bearsteak, 20 Unbroken Claws, 20 Unbroken Teeth and one of each of the three Transmutagens. Cast the recipe when its shared daily transmute cooldown is ready.\n\n5. Keep the Pulsating Sac until its seven-day real-time timer finishes and it becomes a Growling Sac. Open it and learn Transmutant if that is the result. Otherwise repeat the transmute and maturation process; getting an older vendor pet is a normal outcome.",
        wowheadUrl = "https://www.wowhead.com/npc=111425",
    },
    [1921] = {
        category = "Quest Rewards",
        source = "Balance to Spare - Blood and Wine, Suramar",
        itemId = 139790,
        description = "A guaranteed reward from the vineyard chapter of Suramar's story.",
        difficulty = "medium",
        difficultyReason = "Requires reaching the vineyard chapter through several earlier Suramar quests.",
        commentIDs = { 2334412, 2360710 },
        tips = "Old Honored / level-110 requirements describe Legion's launch gates. Follow the Retail story quests; an obsolete reputation gate does not require an extra grind.",
        waypoints = {
            { mapID = 680, x = 0.348, y = 0.48, step = 1, label = "Shal'Aran entrance - Suramar introduction" },
            { mapID = 680, x = 0.58, y = 0.55, step = 2, label = "Twilight Vineyards - Blood and Wine quest area" },
        },
        npcId = 111423,
        petNPCID = 111423,
        name = "Untethered Wyrmling",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Quest Rewards",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Requires reaching the vineyard chapter through several earlier Suramar quests.\n\n1. Complete Suramar's Nightfall introduction and establish Shal'Aran. Continue the available Thalyssra / nightfallen story into the Blood and Wine chapter.\n\n2. Travel to the Twilight Vineyards around 58,55 and follow the Margaux / vineyard resistance quests. Finish the earlier work in this chapter rather than trying to start its final reward quest in isolation.\n\n3. Complete Balance to Spare and collect Untethered Wyrmling as its guaranteed reward. Defeating ordinary mana wyrms does not teach the pet.\n\n4. Use the pet item to learn it, or buy a caged copy from another player if you prefer to bypass the story.",
        wowheadUrl = "https://www.wowhead.com/npc=111423",
        references = {
            "https://www.wowhead.com/npc=111423",
            "https://www.wowhead.com/item=139790",
            "https://www.wowhead.com/npc=111423#comments:id=2334412",
            "https://www.wowhead.com/npc=111423#comments:id=2360710",
        },
    },
    [1922] = {
        category = "Quest Rewards",
        source = "You've Got to Be Kitten Me Right Meow - Suramar",
        itemId = 139791,
        description = "Rescue the owl kittens through a short roadside quest chain.",
        difficulty = "easy",
        difficultyReason = "A small local chain after the Suramar introduction.",
        commentIDs = { 2326054 },
        waypoints = {
            { mapID = 680, x = 0.348, y = 0.48, step = 1, label = "Shal'Aran entrance - Nightfall introduction" },
            { mapID = 680, x = 0.289, y = 0.32799999999999996, step = 2, label = "Feline Frantic - owl kitten rescue chain" },
        },
        npcId = 111421,
        petNPCID = 111421,
        name = "Lurking Owl Kitten",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Quest Rewards",
        stepCount = 4,
        acquisition = "Difficulty: Easy - A small local chain after the Suramar introduction.\n\n1. Complete the Nightfall introduction in Suramar to open the local questing phase around Shal'Aran.\n\n2. Go to 28.9,32.8 northeast of Falanaar, beside the road toward Val'sharah. Accept Feline Frantic and follow it with Homeward Bounding.\n\n3. Complete You've Got to Be Kitten Me Right Meow, the last quest in this short rescue chain, and claim Lurking Owl Kitten.\n\n4. Use the item to learn the dark owl kitten. The white quest NPCs are not separate wild pets to trap.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=111421",
        references = {
            "https://www.wowhead.com/npc=111421",
            "https://www.wowhead.com/item=139791",
            "https://www.wowhead.com/npc=111421#comments:id=2326054",
        },
    },
    [1926] = {
        category = "World Quests",
        source = "DANGER: Kosumoth the Hungering - pet-reward rotation",
        difficulty = "hard",
        description = "Unlock Kosumoth's hidden world quest through the ordered orb secret, then wait for its pet reward.",
        difficultyReason = "A long cross-zone secret followed by a rotating world-quest reward.",
        commentIDs = { 2392934, 6212905 },
        waypoints = {
            { mapID = 646, x = 0.37450000000000006, y = 0.7165, step = 1, label = "Drak'thul - exhaust dialogue" },
            { mapID = 646, x = 0.585, y = 0.54, step = 2, label = "Weathered Relic cave entrance" },
            { mapID = 646, x = 0.574, y = 0.5589999999999999, step = 2, label = "Relic dirt mound inside cave" },
            { mapID = 630, x = 0.3796, y = 0.3739, step = 3, label = "Orb 1 - Azsuna cave" },
            { mapID = 634, x = 0.3283, y = 0.757, step = 4, label = "Orb 2 - Kangaxx cave" },
            { mapID = 641, x = 0.415, y = 0.813, step = 5, label = "Orb 3 - Val'sharah cave" },
            { mapID = 646, x = 0.31, y = 0.75, step = 6, label = "Orb 4 - hidden underwater cave" },
            { mapID = 630, x = 0.5937, y = 0.1308, step = 7, label = "Orb 5 - crystal cave" },
            {
                mapID = 619,
                x = 0.6731999999999999,
                y = 0.1477,
                step = 8,
                label = "Orb 6 - underwater cave north of Shield's Rest",
            },
            { mapID = 650, x = 0.5583, y = 0.385, step = 9, label = "Orb 7 - small bush-hidden cave" },
            { mapID = 630, x = 0.5405, y = 0.2621, step = 10, label = "Orb 8 - tree cave" },
            { mapID = 790, x = 0.7935, y = 0.893, step = 11, label = "Orb 9 - underwater shipwreck cave" },
            { mapID = 646, x = 0.37450000000000006, y = 0.7165, step = 12, label = "Orb 10 - Drak'thul's table" },
            { mapID = 790, x = 0.4696, y = 0.5009, step = 14, label = "Kosumoth - OUTDOOR island / pet-reward world quest" },
        },
        npcId = 111984,
        petNPCID = 111984,
        name = "Hungering Claw",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "World Quests",
        stepCount = 14,
        acquisition = "Difficulty: Hard - A long cross-zone secret followed by a rotating world-quest reward.\n\n1. Unlock Broken Isles world quests through Uniting the Isles. Visit Drak'thul on the Broken Shore at 37.45,71.65 and exhaust his dialogue.\n\n2. Enter the nearby cave from 58.5,54 and search its dirt mound around 57.4,55.9 for the Weathered Relic. Return to Drak'thul and exhaust every new dialogue option, talking again until nothing new remains.\n\n3. Click the ten Hungering Orbs in the following order. An orb skipped or clicked out of order does not complete the secret. Orb 1: enter the Azsuna cave around 37.96,37.39 and click the orb inside.\n\n4. Orb 2: enter the Stormheim cave around 32.83,75.7, deal with Kangaxx and click the orb.\n\n5. Orb 3: enter the Val'sharah cave around 41.5,81.3 and click the orb inside.\n\n6. Orb 4: swim / dive into the hidden Broken Shore cave near 31,75, approaching from the water around 30,77. Search behind the rocks; manage breath and fatigue rather than flying directly at the cliff.\n\n7. Orb 5: enter the Azsuna cave at 59.37,13.08 and click the orb hidden among the crystals.\n\n8. Orb 6: go north of Shield's Rest and use the Broken Isles OVERVIEW pin at 67.32,14.77. Dive into the underwater cave, follow the right passage past the statue and geysers, and click the orb. These are continent coordinates, not Stormheim coordinates.\n\n9. Orb 7: enter the small bush-hidden Highmountain cave at 55.83,38.5. Do not take the nearby large obvious cave.\n\n10. Orb 8: enter the Azsuna cave at 54.05,26.21 by the tree and click its orb.\n\n11. Orb 9: travel to the OUTDOOR Eye of Azshara island, not the dungeon. Dive by the shipwreck toward 79.35,89.3 on the outdoor island map, enter the underwater cave and search the back-right area.\n\n12. Orb 10: return to Drak'thul at 37.45,71.65 and click the orb on his table. This completes the ordered unlock; merely killing Kosumoth before the unlock is not enough.\n\n13. Check DANGER: Kosumoth the Hungering on the outdoor Eye of Azshara. Wait until Hungering Claw is its displayed reward; a Fathom Dweller reward gives the mount instead. Reward periods can repeat, so do not assume strict pet / mount alternation.\n\n14. Defeat Kosumoth at 46.96,50.09 while the pet-reward world quest is active for you. Collect and learn Hungering Claw. A caged copy is also tradable if you prefer to bypass the secret and reward wait.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=111984",
        references = {
            "https://www.wowhead.com/npc=111984",
            "https://www.wowhead.com/npc=111984#comments:id=2392934",
            "https://www.wowhead.com/npc=111984#comments:id=6212905",
        },
    },
    [1927] = {
        category = "Reputation",
        source = "Sylvia Hartshorn - Dreamweavers Revered",
        itemId = 23712,
        description = "A reputation vendor companion. A traded caged copy bypasses the vendor reputation requirement.",
        difficulty = "medium",
        difficultyReason = "The purchase is guaranteed after a reputation grind; a caged pet avoids the grind.",
        requirements = "Revered with Dreamweavers to buy from the vendor",
        cost = "500 gold before reputation discounts",
        commentIDs = { 525154, 2390028 },
        waypoints = { { mapID = 641, x = 0.547, y = 0.733, step = 3, label = "Sylvia Hartshorn - Ash'ana" } },
        npcId = 17254,
        petNPCID = 17254,
        name = "Ash'ana",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Reputation",
        stepCount = 4,
        acquisition = "Difficulty: Medium - The purchase is guaranteed after a reputation grind; a caged pet avoids the grind.\n\n1. Choose between buying a caged Ash'ana on the Auction House or earning it from the faction vendor. The vendor's reputation restriction is not a requirement to learn a caged pet.\n\n2. Complete Val'sharah's story and Dreamweaver world quests / emissaries until Revered. Visit Sylvia in Lorlathil; Dreamweaver Provisions award a different pet, Thistleleaf Adventurer, at random.\n\n3. When Dreamweavers is Revered, visit Sylvia Hartshorn at the recorded destination. Bring 500 gold before any reputation discount and buy Ash'ana.\n\n4. Use the pet item to learn it, then check your Pet Journal. It is a companion purchase; there is no wild capture or pet-battle victory required.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=17254",
        references = {
            "https://www.wowhead.com/npc=17254",
            "https://www.wowhead.com/item=23712",
            "https://www.wowhead.com/npc=17254#comments:id=525154",
            "https://www.wowhead.com/npc=17254#comments:id=2390028",
        },
    },
    [1928] = {
        category = "Order Hall",
        source = "Rare Legion Order Hall mission: Friends, Not Food",
        itemId = 140316,
        description = "A rare mission-table reward available through Legion Order Halls.",
        difficulty = "medium",
        tips = "Use your Legion class hall's mission table: Acherus (Death Knight), Fel Hammer (Demon Hunter), Dreamgrove (Druid), Trueshot Lodge (Hunter), Hall of the Guardian (Mage), Wandering Isle (Monk), Sanctum of Light beneath Light's Hope Chapel (Paladin), Netherlight Temple (Priest), Hall of Shadows (Rogue), Heart of Azeroth at the Maelstrom (Shaman), Dreadscar Rift (Warlock), or Skyhold (Warrior). The recorded areas are alternatives for these halls; Dalaran itself has no shared mission table.",
        difficultyReason = "Waiting for a rare mission and preparing its champions are the main obstacles.",
        commentIDs = { 2327098, 2622655 },
        areaMaps = { 648, 720, 747, 739, 734, 709, 23, 702, 626, 726, 717, 695 },
        npcId = 112132,
        petNPCID = 112132,
        name = "Firebat Pup",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Order Hall",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Waiting for a rare mission and preparing its champions are the main obstacles.\n\n1. Establish a Legion Order Hall on a character and complete its introductory champion recruitment and mission-table quests. Keep Order Resources available and raise your champions through missions / equipment upgrades.\n\n2. Check the mission table for Friends, Not Food. It is a rare rotating mission, so completing an unrelated mission with a similar enemy type does not guarantee this pet mission immediately appears.\n\n3. Inspect the mission's actual reward and enemy counters. Assign champions and troops to reach a reliable success chance before sending them; the pet is the named mission reward, not a promise from arbitrary bonus loot.\n\n4. Wait for completion, collect the successful mission's reward at the table and use Firebat Pup. Repeat later if the mission failed, or compare a caged copy on the Auction House.",
        waypoints = {},
        wowheadUrl = "https://www.wowhead.com/npc=112132",
        references = {
            "https://www.wowhead.com/npc=112132",
            "https://www.wowhead.com/item=140316",
            "https://www.wowhead.com/npc=112132#comments:id=2327098",
            "https://www.wowhead.com/npc=112132#comments:id=2622655",
        },
    },
    [1929] = {
        category = "Order Hall",
        source = "Rare Legion Order Hall mission: It's so FLUFFY!",
        itemId = 140320,
        description = "A rare mission-table reward available through Legion Order Halls.",
        difficulty = "medium",
        tips = "Use your Legion class hall's mission table: Acherus (Death Knight), Fel Hammer (Demon Hunter), Dreamgrove (Druid), Trueshot Lodge (Hunter), Hall of the Guardian (Mage), Wandering Isle (Monk), Sanctum of Light beneath Light's Hope Chapel (Paladin), Netherlight Temple (Priest), Hall of Shadows (Rogue), Heart of Azeroth at the Maelstrom (Shaman), Dreadscar Rift (Warlock), or Skyhold (Warrior). The recorded areas are alternatives for these halls; Dalaran itself has no shared mission table.",
        difficultyReason = "Waiting for a rare mission and preparing its champions are the main obstacles.",
        commentIDs = { 2327097, 2361075 },
        areaMaps = { 648, 720, 747, 739, 734, 709, 23, 702, 626, 726, 717, 695 },
        npcId = 112144,
        petNPCID = 112144,
        name = "Corgnelius",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Order Hall",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Waiting for a rare mission and preparing its champions are the main obstacles.\n\n1. Establish a Legion Order Hall on a character and complete its introductory champion recruitment and mission-table quests. Keep Order Resources available and raise your champions through missions / equipment upgrades.\n\n2. Check the mission table for It's so FLUFFY!. It is a rare rotating mission, so completing an unrelated mission with a similar enemy type does not guarantee this pet mission immediately appears.\n\n3. Inspect the mission's actual reward and enemy counters. Assign champions and troops to reach a reliable success chance before sending them; the pet is the named mission reward, not a promise from arbitrary bonus loot.\n\n4. Wait for completion, collect the successful mission's reward at the table and use Corgnelius. Repeat later if the mission failed, or compare a caged copy on the Auction House.",
        waypoints = {},
        wowheadUrl = "https://www.wowhead.com/npc=112144",
