            "https://www.wowhead.com/npc=112144#comments:id=2327097",
            "https://www.wowhead.com/npc=112144#comments:id=2361075",
        },
    },
    [1930] = {
        category = "Achievements",
        source = "Poor Unfortunate Souls - Mythic Black Rook Hold / Maw of Souls",
        sourceAchievementId = 10412,
        itemId = 140323,
        description = "Carry a chain of timed soul buffs between two Mythic dungeons. Retail no longer requires five players.",
        difficulty = "hard",
        difficultyReason = "A timed two-dungeon sequence, with required boss melee hits that can miss high-level characters.",
        commentUrl = "https://www.wowhead.com/achievement=10412",
        commentIDs = { 5728951, 5815194, 6148947, 6184328, 6327272 },
        waypoints = {
            { mapID = 634, x = 0.607, y = 0.51, step = 1, label = "Valdisdall inn - optional hearth before starting" },
            { mapID = 641, x = 0.38799999999999996, y = 0.51, step = 2, label = "Black Rook Hold - blue brazier inside" },
            { mapID = 634, x = 0.525, y = 0.45, step = 3, label = "Maw of Souls - arrive with Lost Soul" },
        },
        npcId = 112167,
        petNPCID = 112167,
        name = "Lagan",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Achievements",
        stepCount = 7,
        acquisition = "Difficulty: Hard - A timed two-dungeon sequence, with required boss melee hits that can miss high-level characters.\n\n1. Set dungeon difficulty to MYTHIC and start with fresh Black Rook Hold and Maw of Souls lockouts. Arrange fast travel from Val'sharah to Stormheim; setting your hearth at Valdisdall beforehand is useful. This is ordinary Mythic, not a Mythic+ key.\n\n2. Enter Black Rook Hold at 38.8,51.0 in Val'sharah and click the blue brazier in the first room for Wandering Soul. It lasts 30 minutes; simply entering the dungeon does not grant the buff.\n\n3. Clear the entire dungeon, including Lord Kur'talos Ravencrest / Dantalionax. After the final encounter the buff becomes Lost Soul with a shorter ten-minute travel window. Leave immediately and travel to Maw of Souls at 52.5,45.0 in Stormheim. Do not die or wait around after finishing the first dungeon.\n\n4. Enter fresh Mythic Maw of Souls while Lost Soul remains. Engage Ymiron and let him land an actual melee hit BEFORE killing him; this changes the buff to Damned Soul. Turn your back, sit if needed and remove damaging auras / pets that could kill him early. Dodges and misses do not count.\n\n5. Reach Harbaron while Damned Soul remains, let him land a melee hit, and confirm the buff has changed to Poor Unfortunate Soul before killing him. The new buff gives the final short window for Helya.\n\n6. Defeat Helya with Poor Unfortunate Soul still active to complete the achievement. Collect Lagan from the reward / mail and learn him. Modern Retail allows a solo run; older comments demanding a synchronized five-player party are obsolete.\n\n7. If a very high-level character cannot get Ymiron or Harbaron to hit because every swing misses, use a lower-level eligible character with enough damage to clear Mythic, or bring help for that character. Do not keep killing the required bosses without their buff-changing hit: a consumed lockout prevents a same-day retry on that character.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=112167",
        references = {
            "https://www.wowhead.com/npc=112167",
            "https://www.wowhead.com/item=140323",
            "https://www.wowhead.com/achievement=10412#comments:id=5728951",
            "https://www.wowhead.com/achievement=10412#comments:id=5815194",
            "https://www.wowhead.com/achievement=10412#comments:id=6148947",
            "https://www.wowhead.com/achievement=10412#comments:id=6184328",
            "https://www.wowhead.com/achievement=10412#comments:id=6327272",
        },
    },
    [1931] = {
        category = "Reputation",
        source = "Veridis Fallon - Court of Farondis Revered",
        itemId = 140672,
        description = "A reputation vendor companion. A traded caged copy bypasses the vendor reputation requirement.",
        difficulty = "medium",
        difficultyReason = "The purchase is guaranteed after a reputation grind; a caged pet avoids the grind.",
        requirements = "Revered with Court of Farondis to buy from the vendor",
        cost = "500 gold before reputation discounts",
        commentIDs = { 2332729 },
        waypoints = { { mapID = 630, x = 0.46799999999999997, y = 0.414, step = 3, label = "Veridis Fallon - Court Scribe" } },
        npcId = 112728,
        petNPCID = 112728,
        name = "Court Scribe",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Reputation",
        stepCount = 4,
        acquisition = "Difficulty: Medium - The purchase is guaranteed after a reputation grind; a caged pet avoids the grind.\n\n1. Choose between buying a caged Court Scribe on the Auction House or earning it from the faction vendor. The vendor's reputation restriction is not a requirement to learn a caged pet.\n\n2. Complete Azsuna's Court of Farondis story and the faction's world quests / emissaries until Revered. Veridis is in the ruined court near the Crumbled Palace; the scribe is a gold purchase, not a random ghost drop.\n\n3. When Court of Farondis is Revered, visit Veridis Fallon at the recorded destination. Bring 500 gold before any reputation discount and buy Court Scribe.\n\n4. Use the pet item to learn it, then check your Pet Journal. It is a companion purchase; there is no wild capture or pet-battle victory required.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=112728",
        references = {
            "https://www.wowhead.com/npc=112728",
            "https://www.wowhead.com/item=140672",
            "https://www.wowhead.com/npc=112728#comments:id=2332729",
        },
    },
    [1932] = {
        category = "Order Hall",
        source = "Evergreen soil plots - Druid Dreamgrove",
        itemId = 140741,
        description = "A Druid-only acquisition from grown plants; other classes can summon the pet after it is learned.",
        difficulty = "medium",
        difficultyReason = "Needs Druid Order Hall research and repeated three-day harvests.",
        requirements = "A Druid with Evergreen researched",
        commentIDs = { 2339339, 2346826, 2370568, 2495299 },
        tips = "These pets cannot be caged. No retired artifact-power grind is required. Finish an active artifact introduction and the initial champion/mission sequence if Leafbeard still offers no research; the Dreamgrove Researcher is not the upgrade NPC.",
        waypoints = {
            { mapID = 747, x = 0.336, y = 0.28800000000000003, step = 2, label = "Leafbeard - research Evergreen" },
            { mapID = 747, x = 0.452, y = 0.629, step = 3, label = "Evergreen soil plots - plant and harvest" },
        },
        npcId = 112798,
        petNPCID = 112798,
        name = "Nightmare Lasher",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Order Hall",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Needs Druid Order Hall research and repeated three-day harvests.\n\n1. On a Druid, complete the Legion Dalaran introduction, obtain your first artifact and establish the Dreamgrove. Continue The Eternal Dream / Rise, Champions introduction and its early missions until Branching Out opens Order Hall advancements.\n\n2. Speak to Leafbeard the Storied around 33.6,28.8 in the Dreamgrove. Complete the first research tier, then choose Evergreen in the second tier. If you previously chose its alternative, change to Evergreen and wait for the research to finish.\n\n3. Go to the two soil plots around 45.2,62.9 in the Dreamgrove and plant them. Return after their three-day growth period to harvest, then replant the plots.\n\n4. Loot each grown plant. Grove Vines can contain Nightmare Lasher; ordinary harvests can contain food or other items instead. Repeat the planting / harvesting cycle until the pet drops and learn it on the Druid.",
        wowheadUrl = "https://www.wowhead.com/npc=112798",
        references = {
            "https://www.wowhead.com/npc=112798",
            "https://www.wowhead.com/item=140741",
            "https://www.wowhead.com/npc=112798#comments:id=2339339",
