        },
        npcId = 112945,
        petNPCID = 112945,
        name = "Nightmare Treant",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Achievements",
        stepCount = 6,
        acquisition = "Difficulty: Hard - At least 120 qualifying family wins and a varied level-25 pet roster.\n\n1. Open Family Familiar and its ten family sub-achievements. Each family needs ANY 12 of the 15 listed tamers, not all 15. Plan which three difficult fights to skip separately for each family.\n\n2. Unlock Broken Isles world quests through Uniting the Isles and check the eligible pet-battle world quests. These trainers need their active world quest for this achievement route. Check Dalaran's city map too: its tournament quest can be easy to miss on the continent overview.\n\n3. Prepare a three-pet level-25 team entirely from one required family: Aquatic, Beast, Critter, Dragonkin, Elemental, Flying, Humanoid, Magic, Mechanical or Undead. Use pets with off-family attacks to counter the opponent while keeping all three pets' own family correct; a different-family carry invalidates the attempt.\n\n4. Visit an active eligible trainer and win with that family team. The eligible sites include Nightwatcher Merayl in Azsuna; Bredda, Odrogg and Grixis in Highmountain; Robert Craig and Trapper Jarrun in Stormheim; Xorvasc and Durian in Val'sharah; Aulier, Varenne and Flummox in Suramar; and Bodhi, Amalia, Tiffany and Sir Galveston in Dalaran.\n\n5. Heal between attempts and repeat the available trainer with other family teams for missing credit; modern comments report repeat attempts on the same active trainer. Progress Suramar's story if a city trainer is in an incompatible phase. Do not count ordinary wild pet wins or Argus legendary opponents toward Family Familiar.\n\n6. Continue the rotation until each of the ten family achievements has 12 distinct eligible trainers. Collect the Family Familiar reward and learn Nightmare Treant. More pet levels and useful attacks help; character raid gear does not improve pet-battle damage.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=112945",
        references = {
            "https://www.wowhead.com/npc=112945",
            "https://www.wowhead.com/item=140761",
            "https://www.wowhead.com/achievement=9696#comments:id=2531004",
            "https://www.wowhead.com/achievement=9696#comments:id=5546031",
        },
    },
    [1934] = {
        category = "Drops",
        source = "Anax",
        itemId = 140934,
        description = "Obtain the pet item from Anax; do not try to trap the combat NPC.",
        difficulty = "easy",
        difficultyReason = "A short outdoor encounter; the pet is obtained from ordinary loot.",
        commentIDs = { 2336344, 2369354, 2447020 },
        waypoints = { { mapID = 680, x = 0.336, y = 0.518, step = 1, label = "Anax - Benax" } },
        npcId = 113136,
        petNPCID = 113136,
        name = "Benax",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Drops",
        stepCount = 3,
        acquisition = "Difficulty: Easy - A short outdoor encounter; the pet is obtained from ordinary loot.\n\n1. Go to the little island and tree in Meredil's water at 33.6,51.8 in Suramar, close to Shal'Aran. Find the large frog Anax in front of the tree; Benax is his pet drop, not the hostile frog itself.\n\n2. Defeat Anax and loot the body / event reward for Benax. Keep the pet item rather than selling it with ordinary loot.\n\n3. Use Benax to learn the pet. If your eligible loot does not contain it, check again on another eligible character or a later reset; a completed rare-event achievement alone does not teach the pet. A caged copy is an alternative where available.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=113136",
        references = {
            "https://www.wowhead.com/npc=113136",
            "https://www.wowhead.com/item=140934",
            "https://www.wowhead.com/npc=113136#comments:id=2336344",
            "https://www.wowhead.com/npc=113136#comments:id=2369354",
            "https://www.wowhead.com/npc=113136#comments:id=2447020",
        },
    },
    [1937] = {
        category = "Quest Rewards",
        source = "Strange Humming Crystal from Kirin Tor emissary rewards, then Enemies Everywhere",
        itemId = 141348,
        description = "A non-combat companion showing Khadgar's head. The quest-starting crystal is a rare emissary reward.",
        difficulty = "hard",
        difficultyReason = "The emissary rotates and the crystal can require many attempts.",
        commentIDs = { 2332777, 2362672, 3152198, 6089275 },
        references = {
            "https://www.wowhead.com/item=141349/strange-humming-crystal#comments:id=2362669",
            "https://www.wowhead.com/npc=113827",
            "https://www.wowhead.com/item=141348",
            "https://www.wowhead.com/npc=113827#comments:id=2332777",
            "https://www.wowhead.com/npc=113827#comments:id=2362672",
            "https://www.wowhead.com/npc=113827#comments:id=3152198",
            "https://www.wowhead.com/npc=113827#comments:id=6089275",
        },
        tips = "This is a companion that cannot battle. Legion Remix's Bronze vendor was a temporary alternative, not the permanent source. Story phasing can make the companion nonresponsive in newer content without removing the original acquisition quest.",
        waypoints = {
            {
                mapID = 627,
                x = 0.33399999999999996,
                y = 0.47600000000000003,
                step = 2,
                label = "Violet Citadel - Kirin Tor emissary and Khadgar",
            },
        },
        npcId = 113827,
        petNPCID = 113827,
        name = "Wondrous Wisdomball",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Quest Rewards",
        stepCount = 4,
        acquisition = "Difficulty: Hard - The emissary rotates and the crystal can require many attempts.\n\n1. Unlock Broken Isles world quests through Uniting the Isles. When The Kirin Tor of Dalaran emissary is active, complete its four qualifying Kirin Tor world quests before the emissary expires.\n\n2. Return to Warmage Silva near the Violet Citadel in Broken Isles Dalaran and claim the Kirin Tor emissary reward. Open the Kirin Tor Chest and look for Strange Humming Crystal; it is a low-chance extra, not the faction reputation token you choose.\n\n3. Repeat the Kirin Tor emissary on eligible characters whenever it returns until the crystal drops. Other faction emissaries are not a dependable substitute for the Kirin Tor Chest.\n\n4. Use Strange Humming Crystal to start Enemies Everywhere. Follow its instructions and turn it in to Khadgar in the Violet Citadel to receive Wondrous Wisdomball, then use the pet item.",
        wowheadUrl = "https://www.wowhead.com/npc=113827",
    },
    [1938] = {
        category = "Achievements",
        source = "Broken Isles Safari",
        sourceAchievementId = 11233,
        itemId = 141352,
        difficulty = "medium",
        description = "Capture the 35 required wild Broken Isles pets, including hidden and condition-dependent species.",
        difficultyReason = "A six-zone capture circuit with rare replacements, secondary spawns and day / night conditions.",
        commentUrl = "https://www.wowhead.com/achievement=11233",
        commentIDs = { 2373150 },
        waypoints = {
            {
                mapID = 630,
                x = 0.391,
                y = 0.32899999999999996,
                step = 2,
                label = "Rhut'van Divide trail - Kingfeather / Oliveback",
            },
            { mapID = 630, x = 0.56, y = 0.138, step = 2, label = "Ley-Ruins of Zarkhenar - mana fiends, day / night" },
