            { mapID = 650, x = 0.5155, y = 0.37450000000000006, step = 3, label = "Rockcrawler Chasm - Echo Batling entrance" },
            { mapID = 634, x = 0.33, y = 0.55, step = 4, label = "Weeping Bluffs - Stormstruck Beaver" },
            { mapID = 634, x = 0.55, y = 0.43, step = 4, label = "Tideskorn Harbor - Tiny Apparition" },
            { mapID = 641, x = 0.54, y = 0.82, step = 5, label = "Lunarwing Shallows - Shimmering Aquafly" },
            { mapID = 641, x = 0.5, y = 0.7, step = 5, label = "Thas'talah - Spring Strider" },
            { mapID = 680, x = 0.29600000000000004, y = 0.825, step = 6, label = "Lower Felsoul Hold - broodlings" },
            {
                mapID = 680,
