                y = 0.505,
                step = 6,
                label = "Falanaar tunnel entrance - Crystalline Broodling inside",
            },
            { mapID = 627, x = 0.526, y = 0.3, step = 6, label = "Dalaran barber shop - possible Dusty Rug" },
        },
        areaMaps = { 629 },
        npcId = 113855,
        petNPCID = 113855,
        name = "Rescued Fawn",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Achievements",
        stepCount = 7,
        acquisition = "Difficulty: Medium - A six-zone capture circuit with rare replacements, secondary spawns and day / night conditions.\n\n1. Open Broken Isles Safari and use its named criteria as the capture checklist. Bring three healthy level-25 pets and a safe capture attack such as Weakening Blow. Capture below 35% health, then win the whole battle. Quality and breed do not affect achievement credit.\n\n2. In Azsuna, cover the shores for Coastal Sandpiper, Albatross Chick, Juvenile Scuttleback and Slithering Brownscale; the inland grass for Olivetail Hare and Felspider; and Rhut'van Divide for Fledgling Oliveback / Kingfeather. Kingfeather replaces Olivebacks, so clear Oliveback battles while searching. Visit the mana fiends in both day and night periods for Erudite and Eldritch Manafiend.\n\n3. In Highmountain, search Neltharion's Vault for Burrow Spiderling, Rockcrawler Chasm for Echo Batling, the Haglands for Hog-Nosed Bat, rivers for Spiketail Beaver, shores for Coralback Fiddler / Mudshell Conch, and the higher grass / trees for fox kits and Northern Hawk / Long-Eared Owls.\n\n4. In Stormheim, search the Runewood for Black-Footed / Mist Fox Kits, the Weeping Bluffs for Stormstruck Beaver, Tideskorn Harbor for Tiny Apparition, and the cliffs / open ground for Golden Eaglet, Rose Taipan and Long-Eared Owl. Inspect secondary slots too, particularly when primary spawns appear scarce.\n\n5. In Val'sharah, cover Lunarwing Shallows for Shimmering Aquafly, Thas'talah for Spring Strider, Moonclaw / woodland areas for Slithering Brownscale, Auburn Ringtail, Terror Larva, Vale Flitter and Gleamhoof Fawn. Some species also occur in neighboring zones: the species matters, not which valid zone supplied it.\n\n6. In Suramar, search Felsoul Hold for Thornclaw / Vicious Broodlings and the Falanaar tunnels for Crystalline Broodling. The achievement does not require the Alchemy piglets, vendor pets or ordinary outdoor critters. In Legion Dalaran, check the Underbelly for Blind Rat and click a Dusty Rug for Spring Cleaning before capturing Dust Bunny. Use each pet's own guide for its precise search sites and special restrictions.\n\n7. Reopen the achievement and capture any remaining named criteria, including secondary wild pets you encountered along the route. Learned vendor pets do not replace required wild captures. When the Safari completes, collect and learn Rescued Fawn; the fawn itself is not another wild pet to trap.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=113855",
        references = {
            "https://www.wowhead.com/npc=113855",
            "https://www.wowhead.com/item=141352",
