        sourceType = "Order Hall",
        stepCount = 4,
        acquisition = "Difficulty: Easy - Available once the Shaman hall is open and readily won with a prepared level-25 team.\n\n1. On a Shaman, complete the Legion introduction and open the Heart of Azeroth at the Maelstrom. Finish the artifact / hall arrival sequence if necessary; the full class campaign is not required.\n\n2. Find Snowfang beside Aggra and Snowsong at Storm's Eye Overlook, around 35.9,79.3 in the class hall. Bring a healthy level-25 pet team and interact to challenge her.\n\n3. One documented approach is Iron Starlette with Wind-Up, Supercharge and Toxic Smoke: Wind-Up, Supercharge, Wind-Up, then finish with Toxic Smoke. Keep a second strong pet available in case damage rolls differ. A Zandalari Black Claw / Hunting Party team is another option.\n\n4. Win the battle and use Snowfang's Trust from your bags to learn Snowfang. Do not try to trap her or release a learned copy assuming the same Shaman can repeat the reward.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=114063",
        references = {
            "https://www.wowhead.com/npc=114063",
            "https://www.wowhead.com/item=141530",
            "https://www.wowhead.com/npc=114063#comments:id=2335787",
            "https://www.wowhead.com/npc=114063#comments:id=2394733",
            "https://www.wowhead.com/npc=114063#comments:id=2399435",
            "https://www.wowhead.com/npc=114063#comments:id=2448426",
        },
    },
}

